sc_die() {
  printf 'CityB-of-ChatGPT: %s\n' "$*" >&2
  exit 1
}

sc_usage_die() {
  printf 'CityB-of-ChatGPT: %s\nTry: %s help\n' "$*" "${0##*/}" >&2
  exit 2
}

sc_self() {
  local candidate=$0 directory leaf
  if [[ $candidate != /* ]]; then
    candidate=$PWD/${candidate#./}
  fi
  directory=${candidate%/*}
  [[ -n $directory ]] || directory=/
  leaf=${candidate##*/}
  printf '%s/%s\n' "$(cd -P -- "$directory" && pwd)" "$leaf"
}

sc_manual() {
