sc_bootstrap_stream() {
  awk '
    /^__CITYB_OF_CHATGPT_BOOTSTRAP_BEGIN__$/ { inside = 1; next }
    /^__CITYB_OF_CHATGPT_BOOTSTRAP_END__$/ { exit }
    inside { print }
  ' "$(sc_self)" | base64 -d
}

sc_bootstrap_busybox() {
  local host root final temporary actual bytes
  host=$(sc_host_arch)
  [[ $host == "$SC_PAYLOAD_ARCH" ]] || sc_die "bootstrap architecture $SC_PAYLOAD_ARCH cannot run on $host"
  root=$(sc_cache_root)/bootstrap/$SC_BOOTSTRAP_BUSYBOX_SHA256
  final=$root/busybox
  if [[ -f $final && ! -L $final ]]; then
    actual=$(sha256sum "$final" | awk '{print $1}')
    bytes=$(wc -c < "$final" | tr -d '[:space:]')
    if [[ $actual == "$SC_BOOTSTRAP_BUSYBOX_SHA256" && $bytes == "$SC_BOOTSTRAP_BUSYBOX_BYTES" ]]; then
      printf '%s\n' "$final"
      return 0
    fi
    sc_die "bootstrap cache exists but failed verification: $final"
  fi
  [[ ! -e $final && ! -L $final ]] || sc_die "bootstrap cache path is unsafe: $final"
  mkdir -p -- "$root"
  chmod 700 -- "$root"
  temporary=$(mktemp "$root/.busybox.XXXXXXXX")
  trap "rm -f -- $(printf '%q' "$temporary")" EXIT
  sc_bootstrap_stream > "$temporary"
  actual=$(sha256sum "$temporary" | awk '{print $1}')
  bytes=$(wc -c < "$temporary" | tr -d '[:space:]')
  [[ $actual == "$SC_BOOTSTRAP_BUSYBOX_SHA256" && $bytes == "$SC_BOOTSTRAP_BUSYBOX_BYTES" ]] \
    || sc_die 'embedded BusyBox bootstrap identity differs'
  chmod 700 "$temporary"
  if ! mv -T -- "$temporary" "$final" 2>/dev/null; then
    [[ -f $final && ! -L $final && $(sha256sum "$final" | awk '{print $1}') == "$SC_BOOTSTRAP_BUSYBOX_SHA256" ]] \
      || sc_die 'concurrent bootstrap extraction did not produce the expected file'
  fi
  trap - EXIT
  printf '%s\n' "$final"
}

sc_payload_stream() {
  awk '
    /^__CITYB_OF_CHATGPT_PAYLOAD_BEGIN__$/ { inside = 1; next }
    /^__CITYB_OF_CHATGPT_PAYLOAD_END__$/ { exit }
    inside { print }
  ' "$(sc_self)" | base64 -d
}

sc_payload_digest() {
  sc_payload_stream | sha256sum | awk '{print $1}'
}

sc_verify_payload() {
  local json=${1:-0} actual bytes status=pass reason=verified
  [[ $SC_PAYLOAD_SHA256 != UNSEALED && $SC_PAYLOAD_BYTES != 0 ]] || {
    status=fail
    reason=carrier-is-unsealed
  }
  if [[ $status == pass ]]; then
    actual=$(sc_payload_digest) || sc_die 'could not decode embedded payload'
    bytes=$(sc_payload_stream | wc -c | tr -d '[:space:]')
    if [[ $actual != "$SC_PAYLOAD_SHA256" ]]; then
      status=fail
      reason='payload-sha256-mismatch'
    elif [[ $bytes != "$SC_PAYLOAD_BYTES" ]]; then
      status=fail
      reason='payload-length-mismatch'
    elif command -v gzip >/dev/null 2>&1 && ! sc_payload_stream | gzip -t; then
      status=fail
      reason='payload-gzip-invalid'
    fi
  else
    actual=unavailable
    bytes=0
  fi
  if (( json )); then
    printf '{"schema":"%s","status":"%s","reason":"%s","payload_sha256":"%s","payload_bytes":%s,"architecture":"%s"}\n' \
      "$SC_SCHEMA" "$status" "$reason" "$actual" "$bytes" "$SC_PAYLOAD_ARCH"
  else
    printf 'carrier = %s\nstatus = %s\nreason = %s\npayload_sha256 = %s\npayload_bytes = %s\narchitecture = %s\n' \
      "$SC_SCHEMA" "$status" "$reason" "$actual" "$bytes" "$SC_PAYLOAD_ARCH"
  fi
  [[ $status == pass ]]
}

sc_host_arch() {
  case $(uname -m) in
    x86_64|amd64) printf 'x86_64\n' ;;
    aarch64|arm64) printf 'aarch64\n' ;;
    *) uname -m ;;
  esac
}

sc_cache_root() {
  if [[ -n ${CITYB_OF_CHATGPT_HOME:-} ]]; then
    printf '%s\n' "$CITYB_OF_CHATGPT_HOME"
  elif [[ -n ${XDG_CACHE_HOME:-} ]]; then
    printf '%s/cityb-of-chatgpt\n' "$XDG_CACHE_HOME"
  else
    printf '%s/.cache/cityb-of-chatgpt\n' "${HOME:?HOME is required or set CITYB_OF_CHATGPT_HOME}"
  fi
}

sc_verify_tree() {
  local root=$1
  [[ -d $root && ! -L $root ]] || return 1
  (cd -- "$root" && sha256sum -c MANIFEST.sha256 --quiet)
}

sc_payload_root() {
  local host root final temporary busybox
  host=$(sc_host_arch)
  [[ $host == "$SC_PAYLOAD_ARCH" ]] || sc_die "payload architecture $SC_PAYLOAD_ARCH cannot run on $host"
  root=$(sc_cache_root)
  final=$root/$SC_PAYLOAD_SHA256
  if sc_verify_tree "$final"; then
    printf '%s\n' "$final"
    return 0
  fi
  [[ ! -e $final && ! -L $final ]] || sc_die "payload cache exists but failed verification: $final"
  mkdir -p -- "$root"
  chmod 700 -- "$root"
  temporary=$(mktemp -d "$root/.extract.XXXXXXXX")
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  sc_verify_payload 0 >/dev/null
  if command -v gzip >/dev/null 2>&1 && command -v tar >/dev/null 2>&1; then
    sc_payload_stream | gzip -dc | tar -xf - -C "$temporary" --no-same-owner --no-same-permissions
  else
    busybox=$(sc_bootstrap_busybox)
    sc_payload_stream | "$busybox" gzip -dc | "$busybox" tar -xf - -C "$temporary"
  fi
  [[ -d $temporary/cityb-of-chatgpt ]] || sc_die 'payload archive root is absent'
  sc_verify_tree "$temporary/cityb-of-chatgpt" || sc_die 'payload member manifest failed'
  if ! mv -T -- "$temporary/cityb-of-chatgpt" "$final" 2>/dev/null; then
    sc_verify_tree "$final" || sc_die 'concurrent payload extraction did not produce the expected tree'
  fi
  trap - EXIT
  rm -rf -- "$temporary"
  printf '%s\n' "$final"
}

sc_binary() {
  local name=$1 root
  root=$(sc_payload_root)
  case $name in
    cityb|cityb-node|cityb-biggun|argon2) printf '%s/bin/%s/%s\n' "$root" "$SC_PAYLOAD_ARCH" "$name" ;;
    datacube) printf '%s/custody/datacube-rev1227/datacube\n' "$root" ;;
    *) sc_die "unknown embedded binary: $name" ;;
  esac
}

sc_dispatch() {
  local name=$1 binary root
  shift
  binary=$(sc_binary "$name")
  root=$(sc_payload_root)
  [[ -x $binary && ! -L $binary ]] || sc_die "embedded executable is unavailable: $name"
  export CITYB_ARGON2_BIN="$root/bin/$SC_PAYLOAD_ARCH/argon2"
  exec "$binary" "$@"
}

sc_normalize_answers() {
  local input=$1 output=$2 expected=${3:-$SC_ANSWER_COUNT}
  [[ -f $input && ! -L $input ]] || sc_die "answers must be a regular non-symlink file: $input"
  awk -v expected="$expected" '
    BEGIN { count = 0 }
    {
      line = $0
      sub(/\r$/, "", line)
      if (line ~ /^[[:space:]]*```/) next
      sub(/^[[:space:]]*[0-9]+[.)][[:space:]]*/, "", line)
      sub(/^[[:space:]]*[-*][[:space:]]*/, "", line)
      gsub(/^[[:space:]]+|[[:space:]]+$/, "", line)
      if (line == "") next
      fields = split(line, token, /[[:space:]]+/)
      for (field = 1; field <= fields; field++) {
        if (token[field] !~ /^[A-Za-z]+$/) exit 40
        print toupper(token[field])
        count++
      }
    }
    END { if (count != expected) exit 41 }
  ' "$input" > "$output" || sc_die "answers are not exactly $expected one-word ASCII tokens"
}

sc_choir_normalize_answers_soft() {
  local input=$1 output=$2 expected=$SC_CHOIR_ANSWER_COUNT
  [[ -f $input && ! -L $input ]] || return 42
  awk -v expected="$expected" '
    BEGIN { count = 0 }
    {
      line = $0
      sub(/\r$/, "", line)
      if (line ~ /^[[:space:]]*```/) next
      sub(/^[[:space:]]*[0-9]+[.)][[:space:]]*/, "", line)
      sub(/^[[:space:]]*[-*][[:space:]]*/, "", line)
      gsub(/^[[:space:]]+|[[:space:]]+$/, "", line)
      if (line == "") next
      fields = split(line, token, /[[:space:]]+/)
      for (field = 1; field <= fields; field++) {
        sub(/\\+$/, "", token[field])
        gsub(/^[*_`]+|[*_`]+$/, "", token[field])
        if (token[field] !~ /^[A-Za-z]+$/) exit 40
        print toupper(token[field])
        count++
      }
    }
    END { if (count != expected) exit 41 }
  ' "$input" > "$output"
}

sc_choir_canonicalize_answers() {
  local input=$1 output=$2
  cp -- "$input" "$output"
}

sc_office_shift() {
  case $1 in
    reading) printf '3\n' ;;      # Caesar's traditional wheel opens the Reading Office.
    goldilocks) printf '7\n' ;;   # G is the seventh letter.
    tiny) printf '20\n' ;;       # T is the twentieth letter.
    biggun) printf '2\n' ;;       # B is the second letter.
    *) sc_usage_die 'office must be reading|goldilocks|tiny|biggun' ;;
  esac
}

sc_caesar_file() {
  local input=$1 office=$2 output=$3 shift
  shift=$(sc_office_shift "$office")
  awk -v shift="$shift" '
    BEGIN { alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ" }
    {
      rendered = ""
      for (idx = 1; idx <= length($0); idx++) {
        character = substr($0, idx, 1)
        position = index(alphabet, character)
        if (position == 0) rendered = rendered character
        else rendered = rendered substr(alphabet, ((position - 1 + shift) % 26) + 1, 1)
      }
      print rendered
    }
  ' "$input" > "$output"
}

sc_verified_caesar() {
  local input=$1 office=$2 output=$3 temporary answer_sha
  temporary=$(mktemp -d)
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  sc_normalize_answers "$input" "$temporary/answers"
  answer_sha=$(sha256sum "$temporary/answers" | awk '{print $1}')
  [[ $answer_sha == "$SC_ANSWER_COMMITMENT_SHA256" ]] \
    || sc_die 'constitutional transcript commitment disagrees'
  sc_caesar_file "$temporary/answers" "$office" "$output"
  rm -rf -- "$temporary"
  trap - EXIT
}

sc_prompt_caesar() {
  local input=$1 office=$2 json=${3:-0} temporary shift digest
  temporary=$(mktemp -d)
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  sc_verified_caesar "$input" "$office" "$temporary/caesar"
  shift=$(sc_office_shift "$office")
  digest=$(sha256sum "$temporary/caesar" | awk '{print $1}')
  if (( json )); then
    printf '{"schema":"cityb.of-chatgpt.caesar-wheel.v1","office":"%s","shift":%s,"caesar_sha256":"%s","adds_entropy":false,"reversible":true}\n' \
      "$office" "$shift" "$digest"
  else
    cat "$temporary/caesar"
  fi
  rm -rf -- "$temporary"
  trap - EXIT
}

sc_prompt_verify() {
  local input=$1 json=${2:-0} temporary actual status=disagreement admitted=false
  temporary=$(mktemp -d)
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  sc_normalize_answers "$input" "$temporary/answers"
  actual=$(sha256sum "$temporary/answers" | awk '{print $1}')
  if [[ $actual == "$SC_ANSWER_COMMITMENT_SHA256" ]]; then
    status=pass
    admitted=true
  fi
  if (( json )); then
    printf '{"schema":"cityb.of-chatgpt.answer-verification.v3","status":"%s","answer_count":%s,"normalized_sha256":"%s","commitment_match":%s,"reading_office_admitted":%s,"diagnostic_granularity":"whole-transcript"}\n' \
      "$status" "$SC_ANSWER_COUNT" "$actual" "$admitted" "$admitted"
  else
    printf 'status = %s\nanswer_count = %s\nnormalized_sha256 = %s\ncommitment_match = %s\ndiagnostic_granularity = whole-transcript\nreading_office_admitted = %s\nexclusive_possession_proved = false\ngovernance_authority_granted = false\n' \
      "$status" "$SC_ANSWER_COUNT" "$actual" "$admitted" "$admitted"
  fi
  rm -rf -- "$temporary"
  trap - EXIT
  [[ $status == pass ]]
}

sc_role_prompt_verify() {
