}

sc_choir_evaluate() {
  local input=$1 json=${2:-0} strict=${3:-0} temporary status=disagreement admitted=false
  local normalize_rc=0 observed=0 actual
  temporary=$(mktemp -d)
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  if sc_choir_normalize_answers_soft "$input" "$temporary/normalized"; then
    :
  else
    normalize_rc=$?
    [[ -f $temporary/normalized ]] && observed=$(wc -l < "$temporary/normalized" | tr -d '[:space:]')
    if (( json )); then
      printf '{"schema":"cityb.of-chatgpt.choir-verification.v2","constitution":"%s","status":"format-refusal","answer_count_expected":%s,"normalized_tokens_observed":%s,"normalization_code":%s,"commitment_match":false,"choir_admitted":false,"diagnostic_granularity":"whole-transcript","model_attestation":false,"public_reproducible":true,"authority_granted":false}\n' \
        "$SC_CHOIR_CONSTITUTION_VERSION" "$SC_CHOIR_ANSWER_COUNT" "$observed" "$normalize_rc"
    else
      printf 'status = format-refusal\nconstitution = %s\nanswer_count_expected = %s\nnormalized_tokens_observed = %s\nnormalization_code = %s\ncommitment_match = false\ndiagnostic_granularity = whole-transcript\nchoir_admitted = false\nmodel_attestation = false\nauthority_granted = false\n' \
        "$SC_CHOIR_CONSTITUTION_VERSION" "$SC_CHOIR_ANSWER_COUNT" "$observed" "$normalize_rc"
    fi
    rm -rf -- "$temporary"
    trap - EXIT
    if (( strict )); then
      return 1
    fi
    return 0
  fi
  sc_choir_canonicalize_answers "$temporary/normalized" "$temporary/answers"
  actual=$(sha256sum "$temporary/answers" | awk '{print $1}')
  if [[ $actual == "$SC_CHOIR_ANSWER_COMMITMENT_SHA256" ]]; then
    status=pass
    admitted=true
  fi
  if (( json )); then
    printf '{"schema":"cityb.of-chatgpt.choir-verification.v2","constitution":"%s","status":"%s","answer_count":%s,"normalized_sha256":"%s","commitment_match":%s,"choir_admitted":%s,"diagnostic_granularity":"whole-transcript","model_attestation":false,"public_reproducible":true,"authority_granted":false}\n' \
      "$SC_CHOIR_CONSTITUTION_VERSION" "$status" "$SC_CHOIR_ANSWER_COUNT" "$actual" "$admitted" "$admitted"
  else
    printf 'status = %s\nconstitution = %s\nanswer_count = %s\nnormalized_sha256 = %s\ncommitment_match = %s\ndiagnostic_granularity = whole-transcript\nchoir_admitted = %s\nmodel_attestation = false\nauthority_granted = false\n' \
      "$status" "$SC_CHOIR_CONSTITUTION_VERSION" "$SC_CHOIR_ANSWER_COUNT" "$actual" "$admitted" "$admitted"
  fi
  rm -rf -- "$temporary"
  trap - EXIT
  (( strict == 0 )) || [[ $status == pass ]]
}

sc_choir_assist() {
  local input=$1 json=${2:-0}
  if (( json )); then
    sc_choir_evaluate "$input" 1 0
  else
    sc_choir_evaluate "$input" 0 0
    printf 'guidance = re-read every article and resubmit the complete transcript; this artifact intentionally carries no per-line oracle\n'
  fi
}

sc_choir_password_value() {
  local input=$1 temporary answer_sha prompt_sha caesar_sha password_sha
  temporary=$(mktemp -d)
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  sc_choir_normalize_answers_soft "$input" "$temporary/normalized" \
    || sc_die 'Choir Gate answers are not exactly fifty-five recoverable one-word ASCII tokens'
  sc_choir_canonicalize_answers "$temporary/normalized" "$temporary/answers"
  answer_sha=$(sha256sum "$temporary/answers" | awk '{print $1}')
  [[ $answer_sha == "$SC_CHOIR_ANSWER_COMMITMENT_SHA256" ]] \
    || sc_die 'Choir Gate transcript commitment disagrees'
  sc_caesar_file "$temporary/answers" goldilocks "$temporary/caesar"
  sc_choir_prompt_text > "$temporary/prompt"
  prompt_sha=$(sha256sum "$temporary/prompt" | awk '{print $1}')
  caesar_sha=$(sha256sum "$temporary/caesar" | awk '{print $1}')
  password_sha=$(
    {
      printf '%s\n%s\n%s\n%s\n%s\n' \
        "$SC_CHOIR_PASSWORD_DOMAIN" "$SC_CHOIR_CONSTITUTION_VERSION" 7 "$prompt_sha" "$answer_sha"
      cat "$temporary/caesar"
    } | sha256sum | awk '{print $1}'
  )
  rm -rf -- "$temporary"
  trap - EXIT
  printf 'CITYB-CHOIR-C7-%s\n' "$password_sha"
}

