sc_identity_root_value() {
  local answers=$1 office=$2 temporary prompt_sha answer_sha caesar_sha password salt argon2 prehash raw shift
  temporary=$(mktemp -d)
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  sc_normalize_answers "$answers" "$temporary/answers"
  answer_sha=$(sha256sum "$temporary/answers" | awk '{print $1}')
  [[ $answer_sha == "$SC_ANSWER_COMMITMENT_SHA256" ]] \
    || sc_die 'constitutional transcript commitment disagrees'
  sc_caesar_file "$temporary/answers" "$office" "$temporary/caesar"
  sc_prompt_text > "$temporary/prompt"
  prompt_sha=$(sha256sum "$temporary/prompt" | awk '{print $1}')
  caesar_sha=$(sha256sum "$temporary/caesar" | awk '{print $1}')
  password=$(sc_prompt_password_value "$answers" "$office")
  shift=$(sc_office_shift "$office")
  salt=$(printf '%s\n%s\n%s\n%s\n%s\n' \
    "$SC_IDENTITY_DOMAIN" "$SC_CONSTITUTION_VERSION" "$office" "$shift" "$prompt_sha" \
    | sha256sum | awk '{print substr($1,1,32)}')
  prehash=$(
    {
      printf '%s\n%s\n%s\n%s\n%s\n' \
        "$SC_IDENTITY_DOMAIN" "$office" "$password" "$prompt_sha" "$caesar_sha"
      cat "$temporary/caesar"
    } | sha256sum | awk '{print $1}'
  )
  argon2=$(sc_binary argon2)
  raw=$(
    printf '%s' "$prehash" \
      | "$argon2" "$salt" -id -v 13 -k "$SC_ARGON2_MEMORY_KIB" -t "$SC_ARGON2_ITERATIONS" \
          -p "$SC_ARGON2_PARALLELISM" -l "$SC_ARGON2_OUTPUT_BYTES" -r \
      | tr -d '[:space:]'
  ) || sc_die 'Argon2id derivation failed'
  [[ $raw =~ ^[0-9a-f]{64}$ ]] || sc_die 'Argon2id returned an unexpected result'
  rm -rf -- "$temporary"
  trap - EXIT
  printf '%s\n' "$raw"
}

sc_identity_label_value() {
  local answers=$1 office=$2 raw
  raw=$(sc_identity_root_value "$answers" "$office")
  sc_identity_label_from_raw "$office" "$raw"
}

sc_identity_label_from_raw() {
  local office=$1 raw=$2
  [[ $raw =~ ^[0-9a-f]{64}$ ]] || sc_die 'identity root key has an unexpected encoding'
  printf 'chatgpt-%s-%s\n' "$office" \
    "$(printf '%s\n%s\n%s\n' "$SC_IDENTITY_DOMAIN" "$office" "$raw" | sha256sum | awk '{print $1}')"
}

sc_choir_identity_root_value() {
  local answers=$1 temporary prompt_sha answer_sha caesar_sha password salt argon2 prehash raw
  temporary=$(mktemp -d)
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  sc_choir_normalize_answers_soft "$answers" "$temporary/normalized" \
