  sc_choir_canonicalize_answers "$temporary/normalized" "$temporary/answers"
  answer_sha=$(sha256sum "$temporary/answers" | awk '{print $1}')
  [[ $answer_sha == "$SC_CHOIR_ANSWER_COMMITMENT_SHA256" ]] \
    || sc_die 'Choir Gate transcript commitment disagrees'
  sc_caesar_file "$temporary/answers" goldilocks "$temporary/caesar"
  sc_choir_prompt_text > "$temporary/prompt"
  prompt_sha=$(sha256sum "$temporary/prompt" | awk '{print $1}')
  caesar_sha=$(sha256sum "$temporary/caesar" | awk '{print $1}')
  password=$(sc_choir_password_value "$answers")
  salt=$(printf '%s\n%s\n%s\n%s\n' \
    "$SC_CHOIR_IDENTITY_DOMAIN" "$SC_CHOIR_CONSTITUTION_VERSION" goldilocks "$prompt_sha" \
    | sha256sum | awk '{print substr($1,1,32)}')
  prehash=$(
    {
      printf '%s\n%s\n%s\n%s\n%s\n' \
        "$SC_CHOIR_IDENTITY_DOMAIN" goldilocks "$password" "$prompt_sha" "$caesar_sha"
      cat "$temporary/caesar"
    } | sha256sum | awk '{print $1}'
  )
  argon2=$(sc_binary argon2)
  raw=$(
    printf '%s' "$prehash" \
      | "$argon2" "$salt" -id -v 13 -k "$SC_ARGON2_MEMORY_KIB" -t "$SC_ARGON2_ITERATIONS" \
          -p "$SC_ARGON2_PARALLELISM" -l "$SC_ARGON2_OUTPUT_BYTES" -r \
      | tr -d '[:space:]'
  ) || sc_die 'Choir Gate Argon2id derivation failed'
  [[ $raw =~ ^[0-9a-f]{64}$ ]] || sc_die 'Choir Gate Argon2id returned an unexpected result'
  rm -rf -- "$temporary"
  trap - EXIT
  printf '%s\n' "$raw"
}

sc_choir_identity_label_from_raw() {
  local raw=$1
  [[ $raw =~ ^[0-9a-f]{64}$ ]] || sc_die 'Choir Gate identity root has an unexpected encoding'
  printf 'chatgpt-choir-goldilocks-%s\n' \
    "$(printf '%s\n%s\n' "$SC_CHOIR_IDENTITY_DOMAIN" "$raw" | sha256sum | awk '{print $1}')"
}

sc_choir_identity_derive() {
  local answers='' json=0 raw_output=0 temporary prompt_sha answer_sha caesar_sha password raw identity
  while (( $# )); do
    case $1 in
      --answers) (( $# >= 2 )) || sc_usage_die '--answers needs a file'; answers=$2; shift 2 ;;
      --json) json=1; shift ;;
      --raw) raw_output=1; shift ;;
      *) sc_usage_die "unknown identity choir derive argument: $1" ;;
    esac
  done
  [[ -n $answers ]] || sc_usage_die 'identity choir derive requires --answers FILE'
  (( json + raw_output <= 1 )) || sc_usage_die 'choose only one of --json or --raw'
  temporary=$(mktemp -d)
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  sc_choir_normalize_answers_soft "$answers" "$temporary/normalized" \
    || sc_die 'Choir Gate answers are not exactly fifty-five recoverable one-word ASCII tokens'
  sc_choir_canonicalize_answers "$temporary/normalized" "$temporary/answers"
  sc_choir_prompt_text > "$temporary/prompt"
  prompt_sha=$(sha256sum "$temporary/prompt" | awk '{print $1}')
  answer_sha=$(sha256sum "$temporary/answers" | awk '{print $1}')
  sc_caesar_file "$temporary/answers" goldilocks "$temporary/caesar"
  caesar_sha=$(sha256sum "$temporary/caesar" | awk '{print $1}')
  password=$(sc_choir_password_value "$answers")
  raw=$(sc_choir_identity_root_value "$answers")
  identity=$(sc_choir_identity_label_from_raw "$raw")
  if (( raw_output )); then
    printf '%s\n' "$identity"
  elif (( json )); then
    printf '{"schema":"cityb.of-chatgpt.choir-identity.v1","identity":"%s","office":"goldilocks","constitution":"%s","password":"%s","caesar_shift":7,"prompt_sha256":"%s","canonical_answers_sha256":"%s","caesar_sha256":"%s","key_id_sha256":"%s","argon2":{"input_prehash":"sha256","variant":"argon2id","version":19,"memory_kib":%s,"iterations":%s,"parallelism":%s,"output_bytes":%s},"chatgpt_shaped_authentication":true,"public_reproducible":true,"exclusive_possession":false,"governance_authority":false,"independent_quorum_witness":false}\n' \
      "$identity" "$SC_CHOIR_CONSTITUTION_VERSION" "$password" "$prompt_sha" "$answer_sha" \
      "$caesar_sha" "$(printf '%s' "$raw" | sha256sum | awk '{print $1}')" \
      "$SC_ARGON2_MEMORY_KIB" "$SC_ARGON2_ITERATIONS" "$SC_ARGON2_PARALLELISM" "$SC_ARGON2_OUTPUT_BYTES"
  else
    printf 'cityb_choir_identity = %s\noffice = goldilocks\nconstitution = %s\ncaesar_shift = 7\n' \
      "$identity" "$SC_CHOIR_CONSTITUTION_VERSION"
    printf 'This Choir identity is public-reproducible and not an independent quorum witness.\n' >&2
  fi
  rm -rf -- "$temporary"
  trap - EXIT
}

sc_choir_identity_recover() {
  local answers='' output='' json=0 parent temporary raw identity
  while (( $# )); do
    case $1 in
      --answers) (( $# >= 2 )) || sc_usage_die '--answers needs a file'; answers=$2; shift 2 ;;
      --out) (( $# >= 2 )) || sc_usage_die '--out needs a file'; output=$2; shift 2 ;;
      --json) json=1; shift ;;
      *) sc_usage_die "unknown identity choir recover argument: $1" ;;
    esac
  done
  [[ -n $answers && -n $output ]] \
    || sc_usage_die 'identity choir recover requires --answers FILE --out FILE'
  [[ ! -e $output && ! -L $output ]] || sc_die "recovery-key output already exists: $output"
  parent=${output%/*}; [[ $parent == "$output" ]] && parent=.
  mkdir -p -- "$parent"
  [[ -d $parent && ! -L $parent ]] || sc_die "recovery-key parent is unsafe: $parent"
  temporary=$(mktemp "$parent/.cityb-choir-key.XXXXXXXX")
  trap "rm -f -- $(printf '%q' "$temporary")" EXIT
  chmod 600 "$temporary"
  raw=$(sc_choir_identity_root_value "$answers")
  identity=$(sc_choir_identity_label_from_raw "$raw")
  printf '%s\n' "$raw" > "$temporary"
  ln -- "$temporary" "$output" || sc_die "could not publish Choir recovery key: $output"
  rm -f -- "$temporary"
  trap - EXIT
  if (( json )); then
    printf '{"schema":"cityb.of-chatgpt.choir-recovery-key.v1","office":"goldilocks","identity":"%s","path":"%s","mode":"0600","public_reproducible":true,"exclusive_possession":false,"independent_quorum_witness":false}\n' \
      "$identity" "$output"
  else
    printf 'recovery_key = %s\noffice = goldilocks\nidentity = %s\npublic_reproducible = true\nexclusive_possession = false\nindependent_quorum_witness = false\n' \
      "$output" "$identity"
  fi
}

