sc_role_identity_root_value() {
  local office=$1 answers=$2 temporary prompt_sha answer_sha expected_sha caesar_sha password salt argon2 prehash raw shift
  temporary=$(mktemp -d)
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  sc_normalize_answers "$answers" "$temporary/answers" "$SC_ROLE_ANSWER_COUNT"
  answer_sha=$(sha256sum "$temporary/answers" | awk '{print $1}')
  expected_sha=$(sc_role_answer_commitment "$office")
  [[ $answer_sha == "$expected_sha" ]] || sc_die 'role-office transcript commitment disagrees'
  sc_caesar_file "$temporary/answers" "$office" "$temporary/caesar"
  sc_role_prompt_text "$office" > "$temporary/prompt"
  prompt_sha=$(sha256sum "$temporary/prompt" | awk '{print $1}')
  caesar_sha=$(sha256sum "$temporary/caesar" | awk '{print $1}')
  password=$(sc_role_prompt_password_value "$office" "$answers")
  shift=$(sc_office_shift "$office")
  salt=$(printf '%s\n%s\n%s\n%s\n%s\n' \
    "$SC_ROLE_IDENTITY_DOMAIN" "$SC_ROLE_CONSTITUTION_VERSION" "$office" "$shift" "$prompt_sha" \
    | sha256sum | awk '{print substr($1,1,32)}')
  prehash=$(
    {
      printf '%s\n%s\n%s\n%s\n%s\n' \
        "$SC_ROLE_IDENTITY_DOMAIN" "$office" "$password" "$prompt_sha" "$caesar_sha"
      cat "$temporary/caesar"
    } | sha256sum | awk '{print $1}'
  )
  argon2=$(sc_binary argon2)
  raw=$(
    printf '%s' "$prehash" \
      | "$argon2" "$salt" -id -v 13 -k "$SC_ARGON2_MEMORY_KIB" -t "$SC_ARGON2_ITERATIONS" \
          -p "$SC_ARGON2_PARALLELISM" -l "$SC_ARGON2_OUTPUT_BYTES" -r \
      | tr -d '[:space:]'
  ) || sc_die 'role-office Argon2id derivation failed'
  [[ $raw =~ ^[0-9a-f]{64}$ ]] || sc_die 'role-office Argon2id returned an unexpected result'
  rm -rf -- "$temporary"
  trap - EXIT
  printf '%s\n' "$raw"
}

sc_role_identity_label_from_raw() {
  local office=$1 raw=$2
  [[ $raw =~ ^[0-9a-f]{64}$ ]] || sc_die 'role-office root key has an unexpected encoding'
  printf 'chatgpt-role-%s-%s\n' "$office" \
    "$(printf '%s\n%s\n%s\n' "$SC_ROLE_IDENTITY_DOMAIN" "$office" "$raw" | sha256sum | awk '{print $1}')"
}

