sc_office_modes() {
  cat <<'EOF'
CITYB OF CHATGPT · OPERATOR MODES

workshop     Tool/source/Datacube workbench; no external authority by presence.
shared       Legacy common-v3 Goldilocks identity; intentionally recoverable by ChatGPT.
role         Common constitution plus Goldilocks vow; locked compatibility identity.
choir        Closed-lexicon Choir v2; normal empirically shaped collective identity.
private      OS-entropy sovereign operator identity; exclusive custody is possible.
remote       Signed short-lived HTTPS commands; authoritative root remains single-writer.
relay        Signed public fleet kit plus separately encrypted multi-family relay exchange.
courier      Bounded offline QR/file bundles for disconnected routes.
field        Tiny verifies and acts within its provision; it is not an operator keyholder.
truth        Biggun attacks assumptions and reports evidence; it is not governance.

Correspondence authority is real operator authority when granted. It never mints council,
release-signing, provider-secret, or host authority. Those remain separate grants.
EOF
}

sc_office_kit_join() {
  local answers='' root='' input='' json=0 apply=0 role_vow=0 choir=0 parent leaf candidate cityb report identity_kind
  while (( $# )); do
    case $1 in
      --answers) (( $# >= 2 )) || sc_usage_die '--answers needs a file'; answers=$2; shift 2 ;;
      --root) (( $# >= 2 )) || sc_usage_die '--root needs a directory'; root=$2; shift 2 ;;
      --in) (( $# >= 2 )) || sc_usage_die '--in needs a file'; input=$2; shift 2 ;;
      --role-vow) role_vow=1; shift ;;
      --choir) choir=1; shift ;;
      --apply) apply=1; shift ;;
      --json) json=1; shift ;;
      *) sc_usage_die "unknown office kit join argument: $1" ;;
    esac
  done
  [[ -n $answers && -n $root && -n $input ]] \
    || sc_usage_die 'office kit join requires --answers FILE --root DIR --in FILE --apply'
  (( role_vow + choir <= 1 )) || sc_usage_die 'office kit join accepts only one of --role-vow or --choir'
  (( apply )) || sc_usage_die 'office kit join is dry by omission; inspect first, then add --apply'
  [[ ! -e $root && ! -L $root ]] || sc_die "office root must be absent: $root"
  parent=${root%/*}; leaf=${root##*/}
  [[ $parent != "$root" ]] || parent=.
  [[ -d $parent && ! -L $parent ]] || sc_die "office parent must be a real directory: $parent"
  cityb=$(sc_binary cityb)
  "$cityb" correspondence office-kit inspect --in "$input" >/dev/null
  candidate=$(mktemp -d "$parent/.${leaf}.candidate.XXXXXX")
  trap "rm -rf -- $(printf '%q' "$candidate")" EXIT
  if (( choir )); then
    sc_choir_identity_open --answers "$answers" --root "$candidate" --json >/dev/null
  elif (( role_vow )); then
    sc_role_identity_open --office goldilocks --answers "$answers" --root "$candidate" --json >/dev/null
  else
    sc_identity_open --answers "$answers" --root "$candidate" --json >/dev/null
  fi
  report=$("$cityb" correspondence office-kit import --root "$candidate" --in "$input" --apply --json)
  mv -- "$candidate" "$root" || sc_die "could not publish joined office: $root"
  trap - EXIT
  if (( choir )); then
    identity_kind='choir-v2-constitutional'
  elif (( role_vow )); then
    identity_kind='role-vow-constitutional'
  else
    identity_kind='shared-constitutional'
  fi
  if (( json )); then
    # The nested native receipt truthfully names the staging root where import
    # occurred. Publication is a separate atomic rename, so do not present the
    # now-absent staging path as the live office root.
    printf '{"schema":"cityb.of-chatgpt.office-kit-join.v1","success":true,"published":true,"identity_kind":"%s","import_was_staged":true,"import":%s}\n' \
      "$identity_kind" "$report"
  else
    printf 'ChatGPT operator office joined.\nroot = %s\nidentity = %s\nprivate_node_keys_imported = false\nnext = %q office relay --root %q --plan %q/remote-relay-plan.json --apply\n' \
      "$root" "$identity_kind" "$(sc_self)" "$root" "$root"
  fi
}

sc_office() {
  local mode=${1:-} verb cityb
  [[ -n $mode ]] || sc_usage_die 'office needs modes, shared, role, choir, private, remote, kit, relay, courier, gateway, or proof'
  shift
  cityb=$(sc_binary cityb)
  case $mode in
    modes) (( $# == 0 )) || sc_usage_die 'office modes takes no arguments'; sc_office_modes ;;
    shared)
      verb=${1:-}; [[ $verb == open ]] || sc_usage_die 'office shared needs open'; shift
      sc_identity_open "$@"
      ;;
    role)
      verb=${1:-}; [[ $verb == open ]] || sc_usage_die 'office role needs open'; shift
      sc_role_identity_open "$@"
      ;;
    choir)
      verb=${1:-}; [[ $verb == open ]] || sc_usage_die 'office choir needs open'; shift
      sc_choir_identity_open "$@"
      ;;
    private)
      verb=${1:-}; [[ $verb == open ]] || sc_usage_die 'office private needs open'; shift
      "$cityb" correspondence init "$@"
      ;;
    remote) "$cityb" correspondence remote call "$@" ;;
    kit)
      verb=${1:-}; [[ -n $verb ]] || sc_usage_die 'office kit needs export, inspect, import, or join'; shift
      if [[ $verb == join ]]; then
        sc_office_kit_join "$@"
      else
        "$cityb" correspondence office-kit "$verb" "$@"
      fi
      ;;
    relay) "$cityb" correspondence relay exchange "$@" ;;
    courier) "$cityb" correspondence courier "$@" ;;
    gateway) "$cityb" correspondence gateway serve "$@" ;;
    proof) "$cityb" correspondence local-proof "$@" ;;
    *) sc_usage_die 'office needs modes, shared, role, choir, private, remote, kit, relay, courier, gateway, or proof' ;;
  esac
}

sc_doctor() {
  local json=0 status=pass reason=ready command bash_major host bootstrap_sha bootstrap_bytes archive_tools=host
  local proposal_return_available=true proposal_return_reason=ready
  [[ ${1:-} == --json ]] && { json=1; shift; }
  (( $# == 0 )) || sc_usage_die 'doctor accepts only --json'
  for command in awk base64 cat chmod grep install ln mkdir mktemp mv rm sed sha256sum stat tr uname wc; do
    if ! command -v "$command" >/dev/null 2>&1; then
      status=attention
      reason="missing-$command"
      break
    fi
  done
  bash_major=${BASH_VERSINFO[0]}
  if (( bash_major < 4 )); then status=attention; reason=bash-too-old; fi
  host=$(sc_host_arch)
  if [[ $host != "$SC_PAYLOAD_ARCH" ]]; then status=attention; reason=architecture-unavailable; fi
  bootstrap_sha=$(sc_bootstrap_stream | sha256sum | awk '{print $1}')
  bootstrap_bytes=$(sc_bootstrap_stream | wc -c | tr -d '[:space:]')
  if [[ $bootstrap_sha != "$SC_BOOTSTRAP_BUSYBOX_SHA256" || $bootstrap_bytes != "$SC_BOOTSTRAP_BUSYBOX_BYTES" ]]; then
    status=attention
    reason=bootstrap-verification-failed
  elif ! command -v gzip >/dev/null 2>&1 || ! command -v tar >/dev/null 2>&1; then
    archive_tools='embedded-busybox'
  fi
  for command in cmp cut find gzip sort tar xargs; do
    if ! command -v "$command" >/dev/null 2>&1; then
      proposal_return_available=false
      proposal_return_reason="missing-$command"
      break
    fi
  done
  if [[ $proposal_return_available == true ]] \
    && ! tar --version 2>/dev/null | grep -q 'GNU tar'; then
    proposal_return_available=false
    proposal_return_reason=gnu-tar-required
  fi
  if [[ $status == pass ]] && ! sc_verify_payload 0 >/dev/null 2>&1; then
    status=attention
    reason='payload-verification-failed'
  fi
  if (( json )); then
    printf '{"schema":"cityb.of-chatgpt.doctor.v1","status":"%s","reason":"%s","bash_major":%s,"host_arch":"%s","payload_arch":"%s","archive_tools":"%s","proposal_return_available":%s,"proposal_return_reason":"%s","bootstrap_sha256":"%s","nix_required":false,"python_required":false,"network_contacted":false,"persistent_state_created":false}\n' \
      "$status" "$reason" "$bash_major" "$host" "$SC_PAYLOAD_ARCH" "$archive_tools" \
      "$proposal_return_available" "$proposal_return_reason" "$bootstrap_sha"
  else
    printf 'CityB-of-ChatGPT doctor\nstatus = %s\nreason = %s\nbash_major = %s\nhost_arch = %s\npayload_arch = %s\narchive_tools = %s\nproposal_return_available = %s\nproposal_return_reason = %s\nbootstrap_sha256 = %s\nnix_required = false\npython_required = false\nnetwork_contacted = false\npersistent_state_created = false\n' \
      "$status" "$reason" "$bash_major" "$host" "$SC_PAYLOAD_ARCH" "$archive_tools" \
      "$proposal_return_available" "$proposal_return_reason" "$bootstrap_sha"
  fi
  [[ $status == pass ]]
}

sc_version() {
  local json=0
  [[ ${1:-} == --json ]] && { json=1; shift; }
  (( $# == 0 )) || sc_usage_die 'version accepts only --json'
  if (( json )); then
    printf '{"schema":"%s","version":"%s","source_revision":"%s","payload_sha256":"%s","payload_bytes":%s,"payload_arch":"%s","bootstrap_busybox_version":"%s","bootstrap_busybox_sha256":"%s","datacube_release":"%s","datacube_archive_sha256":"%s","choir_constitution":"%s"}\n' \
      "$SC_SCHEMA" "$SC_VERSION" "$SC_SOURCE_REVISION" "$SC_PAYLOAD_SHA256" "$SC_PAYLOAD_BYTES" "$SC_PAYLOAD_ARCH" "$SC_BOOTSTRAP_BUSYBOX_VERSION" "$SC_BOOTSTRAP_BUSYBOX_SHA256" "$SC_DATACUBE_RELEASE" "$SC_DATACUBE_ARCHIVE_SHA256" "$SC_CHOIR_CONSTITUTION_VERSION"
  else
    printf 'CityB-of-ChatGPT %s\nsource %s\npayload %s (%s bytes, %s)\nDatacube %s\n' \
      "$SC_VERSION" "$SC_SOURCE_REVISION" "$SC_PAYLOAD_SHA256" "$SC_PAYLOAD_BYTES" "$SC_PAYLOAD_ARCH" "$SC_DATACUBE_RELEASE"
  fi
}

sc_require_proposal_tools() {
  local command
  for command in awk cmp cut find gzip install ln mkdir mktemp mv sha256sum sort stat tar wc xargs; do
    command -v "$command" >/dev/null 2>&1 || sc_die "proposal operation needs host command: $command"
  done
  tar --version 2>/dev/null | grep -F 'GNU tar' >/dev/null \
    || sc_die 'proposal close/inspect/materialize require GNU tar on the receiving host'
}

sc_safe_relative() {
  local value=$1 component
  local -a components=()
  local IFS=/
  [[ $value =~ ^[A-Za-z0-9.][A-Za-z0-9._+@=/\-]*$ ]] \
    || sc_die "unsafe or noncanonical proposal path: $value"
  [[ $value != /* && $value != */ && $value != *//* ]] \
    || sc_die "unsafe or noncanonical proposal path: $value"
  read -r -a components <<< "$value"
  for component in "${components[@]}"; do
    [[ -n $component && $component != . && $component != .. && $component != .git ]] \
      || sc_die "unsafe proposal path component: $value"
  done
}

sc_tree_manifest() {
  local root=$1 output=$2 metadata after hashes relative raw_mode bytes mtime inode links mode digest line
  local output_parent output_leaf
  local files=0 total=0
  local -A modes=() sizes=()
  [[ -d $root && ! -L $root ]] || sc_die "candidate tree is not a real directory: $root"
  output_parent=${output%/*}; output_leaf=${output##*/}
  [[ $output_parent != "$output" ]] || output_parent=.
  output_parent=$(cd -P -- "$output_parent" && pwd)
  output=$output_parent/$output_leaf
  if find "$root" -mindepth 1 ! -type d ! -type f -print -quit | grep -q .; then
    sc_die 'candidate tree contains a link or special file'
  fi
  if find "$root" -mindepth 1 -type d -empty -print -quit | grep -q .; then
    sc_die 'candidate tree contains an unrepresentable empty directory'
  fi
  metadata=$output.metadata
  after=$output.after
  hashes=$output.hashes
  (cd "$root" && find . -type f -printf '%P\t%m\t%s\t%T@\t%i\t%n\n' | LC_ALL=C sort) > "$metadata"
  : > "$output"
  while IFS=$'\t' read -r relative raw_mode bytes mtime inode links; do
    sc_safe_relative "$relative"
    [[ $links == 1 ]] || sc_die "candidate file has multiple hard links: $relative"
    [[ $raw_mode =~ ^[0-7]{3,4}$ && $bytes =~ ^[0-9]+$ && -n $mtime && -n $inode ]] \
      || sc_die "candidate file metadata is invalid: $relative"
    files=$((files + 1))
    total=$((total + bytes))
    (( files <= SC_PROPOSAL_MAX_FILES )) || sc_die 'candidate file-count bound exceeded'
    (( total <= SC_PROPOSAL_MAX_BYTES )) || sc_die 'candidate byte bound exceeded'
    if (( (8#$raw_mode & 0111) != 0 )); then mode=755; else mode=644; fi
    modes["$relative"]=$mode
    sizes["$relative"]=$bytes
  done < "$metadata"
  if (( files )); then
    (cd "$root" && cut -f1 "$metadata" | xargs -r -d '\n' sha256sum --) > "$hashes"
  else
    : > "$hashes"
  fi
  (cd "$root" && find . -type f -printf '%P\t%m\t%s\t%T@\t%i\t%n\n' | LC_ALL=C sort) > "$after"
  cmp -s "$metadata" "$after" || sc_die 'candidate tree changed while being hashed'
  while IFS= read -r line; do
    digest=${line%% *}
    relative=${line#*  }
    [[ $digest =~ ^[0-9a-f]{64}$ && -n $relative && -n ${modes[$relative]+present} ]] \
      || sc_die 'candidate batch digest output is malformed'
  done < "$hashes"
  while IFS= read -r line; do
    digest=${line%% *}
    relative=${line#*  }
    printf '%s\t%s\t%s\t%s\n' "$digest" "${modes[$relative]}" "${sizes[$relative]}" "$relative" >> "$output"
  done < "$hashes"
  rm -f -- "$metadata" "$after" "$hashes"
  SC_TREE_FILES=$files
  SC_TREE_BYTES=$total
}

sc_source_extract_into() {
  local output=$1 root busybox=''
  [[ ! -e $output && ! -L $output ]] || sc_die "source output must be absent: $output"
  root=$(sc_payload_root)
  mkdir -m 700 -- "$output"
  if command -v tar >/dev/null 2>&1 && command -v gzip >/dev/null 2>&1; then
    tar -xzf "$root/source/cityb-source.tar.gz" -C "$output" --no-same-owner --no-same-permissions
  else
    busybox=$(sc_bootstrap_busybox)
    "$busybox" tar -xzf "$root/source/cityb-source.tar.gz" -C "$output"
  fi
  (cd "$output" && sha256sum -c SOURCE-MANIFEST.sha256 --quiet) \
    || sc_die 'extracted source manifest failed'
}

sc_receipt_value() {
  local key=$1 file=$2 value count
  count=$(grep -c "^${key}=" "$file" || true)
  [[ $count == 1 ]] || sc_die "proposal receipt needs exactly one $key field"
  value=$(sed -n "s/^${key}=//p" "$file")
  [[ -n $value ]] || sc_die "proposal receipt field is empty: $key"
  printf '%s\n' "$value"
}

sc_embedded_source_manifest() {
  local output=$1 root busybox=''
  root=$(sc_payload_root)
  if command -v tar >/dev/null 2>&1 && command -v gzip >/dev/null 2>&1; then
    tar -xOzf "$root/source/cityb-source.tar.gz" ./SOURCE-MANIFEST.sha256 > "$output"
  else
    busybox=$(sc_bootstrap_busybox)
    "$busybox" tar -xOzf "$root/source/cityb-source.tar.gz" ./SOURCE-MANIFEST.sha256 > "$output"
  fi
  [[ -s $output ]] || sc_die 'embedded source manifest is absent'
}

sc_proposal_pack_tree() {
  local tree=$1 output=$2
  [[ ${tree##*/} == "$SC_PROPOSAL_ROOT" ]] || sc_die 'proposal staging root name differs'
  tar --sort=name --mtime='@0' --owner=0 --group=0 --numeric-owner --format=gnu \
    -cf - -C "${tree%/*}" "$SC_PROPOSAL_ROOT" | gzip -n > "$output"
}

sc_proposal_archive_preflight() {
  local archive=$1 listing=$2 verbose=$3 name relative mode owner size date time remainder type
  local members=0 unpack_bytes=0
  [[ -f $archive && ! -L $archive ]] || sc_die 'proposal archive must be a regular non-symlink file'
  [[ $(stat -c '%h' -- "$archive") == 1 ]] || sc_die 'proposal archive must have one hard link'
  (( $(stat -c '%s' -- "$archive") <= SC_PROPOSAL_MAX_ARCHIVE_BYTES )) \
    || sc_die 'proposal archive byte bound exceeded'
  gzip -t -- "$archive" || sc_die 'proposal gzip stream failed verification'
  tar -tzf "$archive" --quoting-style=escape > "$listing"
  [[ -s $listing ]] || sc_die 'proposal archive is empty'
  while IFS= read -r name; do
    [[ $name == "$SC_PROPOSAL_ROOT" || $name == "$SC_PROPOSAL_ROOT/" || $name == "$SC_PROPOSAL_ROOT/"* ]] \
      || sc_die "proposal archive member escapes its fixed root: $name"
    relative=${name#"$SC_PROPOSAL_ROOT"/}
    relative=${relative%/}
    [[ -z $relative ]] || sc_safe_relative "$relative"
  done < "$listing"
  [[ $(LC_ALL=C sort "$listing" | uniq -d | wc -l | tr -d '[:space:]') == 0 ]] \
    || sc_die 'proposal archive contains duplicate member names'
  tar -tvzf "$archive" --numeric-owner --full-time --quoting-style=escape > "$verbose"
  while IFS=' ' read -r mode owner size date time remainder; do
    type=${mode:0:1}
    [[ $type == - || $type == d ]] || sc_die 'proposal archive contains a link or special member'
    [[ $size =~ ^[0-9]+$ && -n $owner && -n $date && -n $time && -n $remainder ]] \
      || sc_die 'proposal archive member metadata is malformed'
    members=$((members + 1))
    unpack_bytes=$((unpack_bytes + size))
    (( members <= SC_PROPOSAL_MAX_MEMBERS )) || sc_die 'proposal archive member-count bound exceeded'
    (( unpack_bytes <= SC_PROPOSAL_MAX_UNPACK_BYTES )) \
      || sc_die 'proposal archive expanded-byte bound exceeded'
  done < "$verbose"
}

sc_proposal_closed_tree_verify() {
  local root=$1 line digest relative actual recorded
  local manifest=$root/MANIFEST.sha256
  [[ -f $manifest && ! -L $manifest ]] || sc_die 'proposal closed-tree manifest is absent or unsafe'
  recorded=$(mktemp)
  actual=$(mktemp)
  : > "$recorded"
  while IFS= read -r line; do
    [[ $line =~ ^([0-9a-f]{64})[[:space:]][[:space:]]\./(.+)$ ]] \
      || sc_die 'proposal closed-tree manifest row is malformed'
    digest=${BASH_REMATCH[1]}
    relative=${BASH_REMATCH[2]}
    sc_safe_relative "$relative"
    [[ $relative != MANIFEST.sha256 ]] || sc_die 'proposal manifest cannot hash itself'
    printf '%s\n' "$relative" >> "$recorded"
  done < "$manifest"
  [[ $(LC_ALL=C sort "$recorded" | uniq -d | wc -l | tr -d '[:space:]') == 0 ]] \
    || sc_die 'proposal manifest contains duplicate paths'
  (cd "$root" && sha256sum -c MANIFEST.sha256 --strict --quiet) \
    || sc_die 'proposal member digest verification failed'
  (cd "$root" && find . -type f ! -path './MANIFEST.sha256' -printf '%P\n' | LC_ALL=C sort) > "$actual"
  LC_ALL=C sort "$recorded" -o "$recorded"
  if ! cmp -s "$recorded" "$actual"; then
    rm -f -- "$recorded" "$actual"
    sc_die 'proposal archive inventory differs from its manifest'
  fi
  rm -f -- "$recorded" "$actual"
}

sc_proposal_unpack() {
  local archive=$1 output=$2 listing verbose root
  sc_require_proposal_tools
  [[ ! -e $output && ! -L $output ]] || sc_die 'proposal extraction output must be absent'
  mkdir -m 700 -- "$output"
  listing=$output.members
  verbose=$output.verbose
  sc_proposal_archive_preflight "$archive" "$listing" "$verbose"
  tar -xzf "$archive" -C "$output" --no-same-owner --no-same-permissions --delay-directory-restore
  root=$output/$SC_PROPOSAL_ROOT
  [[ -d $root && ! -L $root ]] || sc_die 'proposal fixed root is absent or unsafe'
  if find "$root" -mindepth 1 ! -type d ! -type f -print -quit | grep -q .; then
    sc_die 'extracted proposal contains a link or special file'
  fi
  sc_proposal_closed_tree_verify "$root"
  SC_PROPOSAL_EXTRACTED_ROOT=$root
}

sc_proposal_validate_root() {
  local root=$1
  local receipt=$root/PROPOSAL.receipt candidate=$root/CANDIDATE-MANIFEST.tsv
  local generated=$root/.candidate-manifest.generated schema status candidate_sha result_sha base_tree_sha inventory expected required
  [[ -f $receipt && ! -L $receipt && -f $candidate && ! -L $candidate ]] \
    || sc_die 'proposal receipt or candidate manifest is absent'
  for required in PORTABLE-RESULT.txt HOST-VALIDATION.md MANIFEST.sha256 OPERATOR-REQUEST.txt READING-MAP.md BASE-SOURCE-MANIFEST.sha256 BASE-TREE-MANIFEST.tsv; do
    [[ -f $root/$required && ! -L $root/$required ]] || sc_die "proposal member is absent or unsafe: $required"
  done
  [[ -d $root/source && ! -L $root/source ]] || sc_die 'proposal source tree is absent or unsafe'
  inventory=$(mktemp)
  expected=$(mktemp)
  (cd "$root" && find . -mindepth 1 -maxdepth 1 -printf '%P\n' | LC_ALL=C sort) > "$inventory"
  printf '%s\n' BASE-SOURCE-MANIFEST.sha256 BASE-TREE-MANIFEST.tsv CANDIDATE-MANIFEST.tsv HOST-VALIDATION.md MANIFEST.sha256 OPERATOR-REQUEST.txt PORTABLE-RESULT.txt PROPOSAL.receipt READING-MAP.md source \
    | LC_ALL=C sort > "$expected"
  if ! cmp -s "$inventory" "$expected"; then
    rm -f -- "$inventory" "$expected"
    sc_die 'proposal top-level inventory differs'
  fi
  rm -f -- "$inventory" "$expected"
  schema=$(sc_receipt_value schema "$receipt")
  status=$(sc_receipt_value status "$receipt")
  [[ $schema == "$SC_PROPOSAL_SCHEMA" && $status == proposal-not-accepted ]] \
    || sc_die 'proposal receipt schema or status differs'
  SC_PROPOSAL_BASE_REVISION=$(sc_receipt_value base_source_revision "$receipt")
  SC_PROPOSAL_BASE_PAYLOAD=$(sc_receipt_value base_payload_sha256 "$receipt")
  SC_PROPOSAL_BASE_MANIFEST=$(sc_receipt_value base_source_manifest_sha256 "$receipt")
  SC_PROPOSAL_DISPOSITION=$(sc_receipt_value disposition "$receipt")
  SC_PROPOSAL_RECORDED_FILES=$(sc_receipt_value candidate_files "$receipt")
  SC_PROPOSAL_RECORDED_BYTES=$(sc_receipt_value candidate_bytes "$receipt")
  [[ $SC_PROPOSAL_BASE_REVISION =~ ^[0-9a-f]{40}$ \
     && $SC_PROPOSAL_BASE_PAYLOAD =~ ^[0-9a-f]{64}$ \
     && $SC_PROPOSAL_BASE_MANIFEST =~ ^[0-9a-f]{64}$ \
     && $SC_PROPOSAL_RECORDED_FILES =~ ^[0-9]+$ \
     && $SC_PROPOSAL_RECORDED_BYTES =~ ^[0-9]+$ ]] \
    || sc_die 'proposal receipt contains an invalid identity or count'
  case $SC_PROPOSAL_DISPOSITION in ask|recommend|hold|reject) ;; *) sc_die 'proposal disposition differs' ;; esac
  candidate_sha=$(sc_receipt_value candidate_manifest_sha256 "$receipt")
  result_sha=$(sc_receipt_value portable_result_sha256 "$receipt")
  base_tree_sha=$(sc_receipt_value base_tree_manifest_sha256 "$receipt")
  [[ $SC_PROPOSAL_BASE_MANIFEST == "$(sha256sum "$root/BASE-SOURCE-MANIFEST.sha256" | awk '{print $1}')" ]] \
    || sc_die 'proposal carried base-source manifest identity differs'
  [[ $(sc_receipt_value operator_request_sha256 "$receipt") == "$(sha256sum "$root/OPERATOR-REQUEST.txt" | awk '{print $1}')" ]] \
    || sc_die 'proposal carried operator request identity differs'
  [[ $(sc_receipt_value reading_map_sha256 "$receipt") == "$(sha256sum "$root/READING-MAP.md" | awk '{print $1}')" ]] \
    || sc_die 'proposal carried reading map identity differs'
  [[ $candidate_sha == "$(sha256sum "$candidate" | awk '{print $1}')" ]] \
    || sc_die 'proposal candidate-manifest identity differs'
  [[ $base_tree_sha == "$(sha256sum "$root/BASE-TREE-MANIFEST.tsv" | awk '{print $1}')" ]] \
    || sc_die 'proposal base-tree-manifest identity differs'
  [[ $result_sha == "$(sha256sum "$root/PORTABLE-RESULT.txt" | awk '{print $1}')" ]] \
    || sc_die 'proposal portable-result identity differs'
  sc_tree_manifest "$root/source" "$generated"
  cmp -s "$generated" "$candidate" || sc_die 'proposal source differs from its candidate manifest'
  [[ $SC_TREE_FILES == "$SC_PROPOSAL_RECORDED_FILES" && $SC_TREE_BYTES == "$SC_PROPOSAL_RECORDED_BYTES" ]] \
    || sc_die 'proposal candidate counts differ'
  rm -f -- "$generated" "$generated.names"
}

sc_open() {
  local out='' request='' root self parent leaf staging source_manifest source_manifest_sha request_sha map_sha
  while (( $# )); do
    case $1 in
      --out) (( $# >= 2 )) || sc_usage_die '--out needs a directory'; out=$2; shift 2 ;;
      --request) (( $# >= 2 )) || sc_usage_die '--request needs a file'; request=$2; shift 2 ;;
      *) sc_usage_die "unknown open argument: $1" ;;
    esac
  done
  [[ -n $out ]] || sc_usage_die 'open requires --out DIR'
  [[ ! -e $out && ! -L $out ]] || sc_die "office output must be absent: $out"
  if [[ -n $request ]]; then
    [[ -f $request && ! -L $request ]] || sc_die 'request must be a regular non-symlink file'
    (( $(stat -c '%s' -- "$request") <= SC_PROPOSAL_MAX_REQUEST_BYTES )) \
      || sc_die 'request byte bound exceeded'
  fi
  root=$(sc_payload_root)
  parent=${out%/*}; leaf=${out##*/}
  [[ $parent != "$out" ]] || parent=.
  [[ -d $parent && ! -L $parent && -n $leaf && $leaf != . && $leaf != .. ]] \
    || sc_die 'office output parent or leaf is unsafe'
  staging=$(mktemp -d "$parent/.${leaf}.cityb-office.XXXXXXXX")
  trap "rm -rf -- $(printf '%q' "$staging")" EXIT
  mkdir -m 700 -- "$staging/bin" "$staging/state" "$staging/result" "$staging/.cityb-of-chatgpt"
  self=$(sc_self)
  install -m 700 -- "$self" "$staging/bin/CityB-of-ChatGPT.sh"
  sc_source_extract_into "$staging/source"
  source_manifest=$staging/source/SOURCE-MANIFEST.sha256
  source_manifest_sha=$(sha256sum "$source_manifest" | awk '{print $1}')
  mv -- "$source_manifest" "$staging/.cityb-of-chatgpt/base-source-manifest.sha256"
  if [[ -n $request ]]; then
    install -m 600 -- "$request" "$staging/OPERATOR-REQUEST.txt"
  else
    printf '%s\n' 'Write the current operator request here. Inherited source does not supply it.' > "$staging/OPERATOR-REQUEST.txt"
    chmod 600 "$staging/OPERATOR-REQUEST.txt"
  fi
  cat > "$staging/READING-MAP.md" <<'EOF'
# CityB of ChatGPT office

1. Read `OPERATOR-REQUEST.txt` as the current request.
2. Run `bin/CityB-of-ChatGPT.sh manual`, `doctor`, and `verify`.
3. Read and edit the complete verified donor estate under `source/`.
4. Run `bin/CityB-of-ChatGPT.sh cockpit --root ./state` when retained CityB state exists.
5. Use `bin/CityB-of-ChatGPT.sh datacube run`, `project-summary`, `project-find`, or other explicit
   Datacube operations when continuity work is required.
6. Put one attributed result outside `source/`, then close the office with
   `bin/CityB-of-ChatGPT.sh proposal close --workspace . --result FILE
   --disposition recommend --output ../cityb-proposal.tar.gz`.
7. The return is a complete proposal. It never accepts, installs, executes,
   publishes, or activates itself on the receiving host.
EOF
  chmod 600 "$staging/READING-MAP.md"
  request_sha=$(sha256sum "$staging/OPERATOR-REQUEST.txt" | awk '{print $1}')
  map_sha=$(sha256sum "$staging/READING-MAP.md" | awk '{print $1}')
  cat > "$staging/.cityb-of-chatgpt/receipt" <<EOF
schema=$SC_PROPOSAL_WORKSPACE_SCHEMA
payload_sha256=$SC_PAYLOAD_SHA256
source_revision=$SC_SOURCE_REVISION
base_source_manifest_sha256=$source_manifest_sha
operator_request_sha256=$request_sha
reading_map_sha256=$map_sha
EOF
  chmod 600 "$staging/READING-MAP.md" "$staging/.cityb-of-chatgpt/receipt" \
    "$staging/.cityb-of-chatgpt/base-source-manifest.sha256"
  mv -T -- "$staging" "$out" || sc_die "could not publish office: $out"
  trap - EXIT
  printf 'office = %s\npayload = %s\nsource = %s\nrequest = %s\nnext = cd %q && bin/CityB-of-ChatGPT.sh cockpit --root ./state\n' \
    "$out" "$SC_PAYLOAD_SHA256" "$SC_SOURCE_REVISION" "$out/OPERATOR-REQUEST.txt" "$out"
  : "$root"
}

sc_workspace_validate() {
  local workspace=$1
  local receipt=$workspace/.cityb-of-chatgpt/receipt base=$workspace/.cityb-of-chatgpt/base-source-manifest.sha256
  local schema payload revision manifest_sha request_sha map_sha
  [[ -d $workspace && ! -L $workspace ]] || sc_die 'proposal workspace must be a real directory'
  [[ -f $receipt && ! -L $receipt && -f $base && ! -L $base ]] \
    || sc_die 'proposal workspace custody receipt is absent or unsafe'
  schema=$(sc_receipt_value schema "$receipt")
  payload=$(sc_receipt_value payload_sha256 "$receipt")
  revision=$(sc_receipt_value source_revision "$receipt")
  manifest_sha=$(sc_receipt_value base_source_manifest_sha256 "$receipt")
  request_sha=$(sc_receipt_value operator_request_sha256 "$receipt")
  map_sha=$(sc_receipt_value reading_map_sha256 "$receipt")
  [[ $schema == "$SC_PROPOSAL_WORKSPACE_SCHEMA" ]] || sc_die 'workspace receipt schema differs'
  [[ $payload == "$SC_PAYLOAD_SHA256" && $revision == "$SC_SOURCE_REVISION" ]] \
    || sc_die 'workspace was not opened by this exact carrier base'
  [[ $manifest_sha == "$(sha256sum "$base" | awk '{print $1}')" ]] \
    || sc_die 'workspace base source manifest identity differs'
  [[ $request_sha == "$(sha256sum "$workspace/OPERATOR-REQUEST.txt" | awk '{print $1}')" ]] \
    || sc_die 'workspace current request changed after admission'
  [[ $map_sha == "$(sha256sum "$workspace/READING-MAP.md" | awk '{print $1}')" ]] \
    || sc_die 'workspace reading map changed after admission'
  SC_WORKSPACE_BASE_MANIFEST_SHA=$manifest_sha
  SC_WORKSPACE_REQUEST_SHA=$request_sha
  SC_WORKSPACE_READING_MAP_SHA=$map_sha
}

sc_proposal_close() {
  local workspace='' result='' disposition='' output='' json=0 parent leaf temporary tree candidate relative_parent
  local result_sha candidate_sha archive_tmp archive_sha receipt base base_source base_tree base_tree_sha source_manifest
  local candidate_files candidate_bytes
  while (( $# )); do
    case $1 in
      --workspace) (( $# >= 2 )) || sc_usage_die '--workspace needs a directory'; workspace=$2; shift 2 ;;
      --result) (( $# >= 2 )) || sc_usage_die '--result needs a file'; result=$2; shift 2 ;;
      --disposition) (( $# >= 2 )) || sc_usage_die '--disposition needs a value'; disposition=$2; shift 2 ;;
      --output) (( $# >= 2 )) || sc_usage_die '--output needs a file'; output=$2; shift 2 ;;
      --json) json=1; shift ;;
      *) sc_usage_die "unknown proposal close argument: $1" ;;
    esac
  done
  [[ -n $workspace && -n $result && -n $disposition && -n $output ]] \
    || sc_usage_die 'proposal close requires --workspace DIR --result FILE --disposition VALUE --output FILE'
  case $disposition in ask|recommend|hold|reject) ;; *) sc_usage_die 'disposition must be ask|recommend|hold|reject' ;; esac
  [[ -f $result && ! -L $result ]] || sc_die 'portable result must be a regular non-symlink file'
  [[ $(stat -c '%h' -- "$result") == 1 ]] || sc_die 'portable result must have one hard link'
  (( $(stat -c '%s' -- "$result") <= SC_PROPOSAL_MAX_RESULT_BYTES )) \
    || sc_die 'portable result byte bound exceeded'
  [[ ! -e $output && ! -L $output ]] || sc_die 'proposal output must be absent'
  sc_require_proposal_tools
  sc_workspace_validate "$workspace"
  parent=${output%/*}; leaf=${output##*/}; [[ $parent != "$output" ]] || parent=.
  [[ -d $parent && ! -L $parent && -n $leaf && $leaf != . && $leaf != .. ]] \
    || sc_die 'proposal output parent or leaf is unsafe'
  temporary=$(mktemp -d "$parent/.${leaf}.proposal.XXXXXXXX")
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  tree=$temporary/$SC_PROPOSAL_ROOT
  mkdir -m 700 -- "$tree" "$tree/source"
  candidate=$tree/CANDIDATE-MANIFEST.tsv
  sc_tree_manifest "$workspace/source" "$candidate"
  candidate_files=$SC_TREE_FILES
  candidate_bytes=$SC_TREE_BYTES
  while IFS=$'\t' read -r _digest mode _bytes relative; do
    relative_parent=${relative%/*}
    [[ $relative_parent == "$relative" ]] && relative_parent=.
    mkdir -p -- "$tree/source/$relative_parent"
    install -m "$mode" -- "$workspace/source/$relative" "$tree/source/$relative"
  done < "$candidate"
  base=$workspace/.cityb-of-chatgpt/base-source-manifest.sha256
  base_source=$temporary/base-source
  sc_source_extract_into "$base_source"
  source_manifest=$base_source/SOURCE-MANIFEST.sha256
  [[ $SC_WORKSPACE_BASE_MANIFEST_SHA == "$(sha256sum "$source_manifest" | awk '{print $1}')" ]] \
    || sc_die 'workspace donor manifest differs from the exact carrier source'
  mv -- "$source_manifest" "$temporary/embedded-source-manifest.sha256"
  base_tree=$tree/BASE-TREE-MANIFEST.tsv
  sc_tree_manifest "$base_source" "$base_tree"
  base_tree_sha=$(sha256sum "$base_tree" | awk '{print $1}')
  install -m 600 -- "$result" "$tree/PORTABLE-RESULT.txt"
  install -m 600 -- "$workspace/OPERATOR-REQUEST.txt" "$tree/OPERATOR-REQUEST.txt"
  install -m 600 -- "$workspace/READING-MAP.md" "$tree/READING-MAP.md"
  install -m 600 -- "$base" "$tree/BASE-SOURCE-MANIFEST.sha256"
  cat > "$tree/HOST-VALIDATION.md" <<'EOF'
# CityB of ChatGPT returned proposal

This archive is a complete candidate source estate, not accepted source. Inspect
it with the exact base carrier, materialize it only into an absent directory,
review the complete diff, run host-side builds and tests, and make a separate
human adoption decision. Nothing in this proposal authorizes installation,
provider mutation, release signing, publication, or activation.
EOF
  candidate_sha=$(sha256sum "$candidate" | awk '{print $1}')
  result_sha=$(sha256sum "$tree/PORTABLE-RESULT.txt" | awk '{print $1}')
  receipt=$tree/PROPOSAL.receipt
  cat > "$receipt" <<EOF
schema=$SC_PROPOSAL_SCHEMA
status=proposal-not-accepted
base_source_revision=$SC_SOURCE_REVISION
base_payload_sha256=$SC_PAYLOAD_SHA256
base_source_manifest_sha256=$SC_WORKSPACE_BASE_MANIFEST_SHA
base_tree_manifest_sha256=$base_tree_sha
operator_request_sha256=$SC_WORKSPACE_REQUEST_SHA
reading_map_sha256=$SC_WORKSPACE_READING_MAP_SHA
candidate_manifest_sha256=$candidate_sha
portable_result_sha256=$result_sha
candidate_files=$candidate_files
candidate_bytes=$candidate_bytes
disposition=$disposition
host_write=false
host_test=false
acceptance=false
activation=false
EOF
  (cd "$tree" && find . -type f ! -path './MANIFEST.sha256' -print0 | LC_ALL=C sort -z \
    | while IFS= read -r -d '' path; do sha256sum "$path"; done) > "$tree/MANIFEST.sha256"
  archive_tmp=$temporary/archive.tar.gz
  sc_proposal_pack_tree "$tree" "$archive_tmp"
  archive_sha=$(sha256sum "$archive_tmp" | awk '{print $1}')
  chmod 600 "$archive_tmp"
  ln -- "$archive_tmp" "$output" || sc_die 'could not atomically publish proposal archive'
  if (( json )); then
    printf '{"schema":"cityb.of-chatgpt.proposal-close.v1","status":"pass","archive_sha256":"%s","base_source_revision":"%s","candidate_files":%s,"candidate_bytes":%s,"disposition":"%s","proposal_not_accepted":true,"host_write":false,"acceptance":false,"activation":false}\n' \
      "$archive_sha" "$SC_SOURCE_REVISION" "$candidate_files" "$candidate_bytes" "$disposition"
  else
    printf 'status = pass\nproposal = %q\narchive_sha256 = %s\nbase_source_revision = %s\ncandidate_files = %s\ncandidate_bytes = %s\ndisposition = %s\nproposal_not_accepted = true\nnext = %q proposal inspect %q\n' \
      "$output" "$archive_sha" "$SC_SOURCE_REVISION" "$candidate_files" "$candidate_bytes" "$disposition" "$(sc_self)" "$output"
  fi
  rm -rf -- "$temporary"
  trap - EXIT
  : "$base"
}

sc_proposal_changes() {
  local base=$1 candidate=$2 output=$3
  local base_tsv=$output.base.tsv candidate_tsv=$output.candidate.tsv
  awk -F '\t' '{print $4 "\t" $1 ":" $2}' "$base" | LC_ALL=C sort > "$base_tsv"
  awk -F '\t' '{print $4 "\t" $1 ":" $2}' "$candidate" | LC_ALL=C sort > "$candidate_tsv"
  awk -F '\t' -v added="$output.added" -v modified="$output.modified" -v deleted="$output.deleted" '
    NR == FNR { base[$1] = $2; next }
    { candidate[$1] = $2; if (!($1 in base)) print $1 > added; else if (base[$1] != $2) print $1 > modified }
    END { for (path in base) if (!(path in candidate)) print path > deleted }
  ' "$base_tsv" "$candidate_tsv"
  for kind in added modified deleted; do
    [[ -f $output.$kind ]] || : > "$output.$kind"
    LC_ALL=C sort "$output.$kind" -o "$output.$kind"
  done
}

sc_proposal_inspect() {
  local archive='' json=0 temporary root embedded base_sha base_match=false changes added modified deleted archive_sha
  local actual_base actual_manifest actual_base_tree
  while (( $# )); do
    case $1 in
      --json) json=1; shift ;;
      --*) sc_usage_die "unknown proposal inspect argument: $1" ;;
      *) [[ -z $archive ]] || sc_usage_die 'proposal inspect accepts one archive'; archive=$1; shift ;;
    esac
  done
  [[ -n $archive ]] || sc_usage_die 'proposal inspect requires ARCHIVE'
  temporary=$(mktemp -d)
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  sc_proposal_unpack "$archive" "$temporary/unpack"
  root=$SC_PROPOSAL_EXTRACTED_ROOT
  sc_proposal_validate_root "$root"
  embedded=$temporary/embedded-source-manifest.sha256
  sc_embedded_source_manifest "$embedded"
  base_sha=$(sha256sum "$embedded" | awk '{print $1}')
  if [[ $SC_PROPOSAL_BASE_REVISION == "$SC_SOURCE_REVISION" \
     && $SC_PROPOSAL_BASE_PAYLOAD == "$SC_PAYLOAD_SHA256" \
     && $SC_PROPOSAL_BASE_MANIFEST == "$base_sha" ]]; then
    base_match=true
    actual_base=$temporary/current-base
    sc_source_extract_into "$actual_base"
    actual_manifest=$actual_base/SOURCE-MANIFEST.sha256
    mv -- "$actual_manifest" "$temporary/current-base-source-manifest.sha256"
    actual_base_tree=$temporary/current-base-tree-manifest.tsv
    sc_tree_manifest "$actual_base" "$actual_base_tree"
    cmp -s "$actual_base_tree" "$root/BASE-TREE-MANIFEST.tsv" \
      || sc_die 'proposal base tree differs from the exact current carrier source'
    changes=$temporary/changes
    sc_proposal_changes "$actual_base_tree" "$root/CANDIDATE-MANIFEST.tsv" "$changes"
    added=$(wc -l < "$changes.added" | tr -d '[:space:]')
    modified=$(wc -l < "$changes.modified" | tr -d '[:space:]')
    deleted=$(wc -l < "$changes.deleted" | tr -d '[:space:]')
  else
    added=0; modified=0; deleted=0
  fi
  archive_sha=$(sha256sum "$archive" | awk '{print $1}')
  if (( json )); then
    printf '{"schema":"cityb.of-chatgpt.proposal-inspection.v1","status":"pass","archive_sha256":"%s","base_source_revision":"%s","current_base_match":%s,"candidate_files":%s,"candidate_bytes":%s,"disposition":"%s","changes":{"added":%s,"modified":%s,"deleted":%s},"proposal_not_accepted":true,"materialize_allowed":%s,"host_test":false,"acceptance":false,"activation":false}\n' \
      "$archive_sha" "$SC_PROPOSAL_BASE_REVISION" "$base_match" "$SC_PROPOSAL_RECORDED_FILES" "$SC_PROPOSAL_RECORDED_BYTES" "$SC_PROPOSAL_DISPOSITION" "$added" "$modified" "$deleted" "$base_match"
  else
    printf 'status = pass\narchive_sha256 = %s\nbase_source_revision = %s\ncurrent_base_match = %s\ncandidate_files = %s\ncandidate_bytes = %s\ndisposition = %s\nchanges = +%s ~%s -%s\nproposal_not_accepted = true\nmaterialize_allowed = %s\n' \
      "$archive_sha" "$SC_PROPOSAL_BASE_REVISION" "$base_match" "$SC_PROPOSAL_RECORDED_FILES" "$SC_PROPOSAL_RECORDED_BYTES" "$SC_PROPOSAL_DISPOSITION" "$added" "$modified" "$deleted" "$base_match"
    if [[ $base_match == true ]]; then
      printf 'change_preview:\n'
      sed -n '1,8{s/^/  + /;p}' "$changes.added"
      sed -n '1,8{s/^/  ~ /;p}' "$changes.modified"
      sed -n '1,8{s/^/  - /;p}' "$changes.deleted"
      printf 'next = %q proposal materialize %q --out ABSENT_DIRECTORY\n' "$(sc_self)" "$archive"
    else
      printf 'next = reacquire the exact base carrier named by base_source_revision\n'
    fi
  fi
  rm -rf -- "$temporary"
  trap - EXIT
}

sc_proposal_materialize() {
  local archive='' output='' json=0 parent leaf temporary root embedded base_sha staging
  while (( $# )); do
    case $1 in
      --out) (( $# >= 2 )) || sc_usage_die '--out needs a directory'; output=$2; shift 2 ;;
      --json) json=1; shift ;;
      --*) sc_usage_die "unknown proposal materialize argument: $1" ;;
      *) [[ -z $archive ]] || sc_usage_die 'proposal materialize accepts one archive'; archive=$1; shift ;;
    esac
  done
  [[ -n $archive && -n $output ]] || sc_usage_die 'proposal materialize requires ARCHIVE --out ABSENT_DIRECTORY'
  [[ ! -e $output && ! -L $output ]] || sc_die 'proposal materialization output must be absent'
  parent=${output%/*}; leaf=${output##*/}; [[ $parent != "$output" ]] || parent=.
  [[ -d $parent && ! -L $parent && -n $leaf && $leaf != . && $leaf != .. ]] \
    || sc_die 'proposal materialization parent or leaf is unsafe'
  temporary=$(mktemp -d "$parent/.${leaf}.materialize.XXXXXXXX")
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  sc_proposal_unpack "$archive" "$temporary/unpack"
  root=$SC_PROPOSAL_EXTRACTED_ROOT
  sc_proposal_validate_root "$root"
  embedded=$temporary/embedded-source-manifest.sha256
  sc_embedded_source_manifest "$embedded"
  base_sha=$(sha256sum "$embedded" | awk '{print $1}')
  [[ $SC_PROPOSAL_BASE_REVISION == "$SC_SOURCE_REVISION" \
     && $SC_PROPOSAL_BASE_PAYLOAD == "$SC_PAYLOAD_SHA256" \
     && $SC_PROPOSAL_BASE_MANIFEST == "$base_sha" ]] \
    || sc_die 'proposal base differs from this carrier; materialization refused'
  staging=$temporary/candidate
  mv -- "$root/source" "$staging"
  mv -T -- "$staging" "$output" || sc_die 'could not publish materialized candidate'
  if (( json )); then
    printf '{"schema":"cityb.of-chatgpt.proposal-materialization.v1","status":"pass","base_source_revision":"%s","candidate_files":%s,"candidate_bytes":%s,"new_directory_write":true,"source_checkout_write":false,"host_test":false,"acceptance":false,"activation":false}\n' \
      "$SC_SOURCE_REVISION" "$SC_PROPOSAL_RECORDED_FILES" "$SC_PROPOSAL_RECORDED_BYTES"
  else
    printf 'status = pass\ncandidate = %q\nbase_source_revision = %s\ncandidate_files = %s\ncandidate_bytes = %s\nsource_checkout_write = false\nhost_test = false\nacceptance = false\nnext = review the complete candidate diff and run host-side tests\n' \
      "$output" "$SC_SOURCE_REVISION" "$SC_PROPOSAL_RECORDED_FILES" "$SC_PROPOSAL_RECORDED_BYTES"
  fi
  rm -rf -- "$temporary"
  trap - EXIT
}

sc_proposal_proof() {
  local json=0 temporary self
  [[ ${1:-} == --json ]] && { json=1; shift; }
  (( $# == 0 )) || sc_usage_die 'proposal proof accepts only --json'
  temporary=$(mktemp -d)
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  self=$(sc_self)
  printf '%s\n' 'Exercise one complete CityB cloudtainer proposal return.' > "$temporary/request.txt"
  sc_open --request "$temporary/request.txt" --out "$temporary/office" >/dev/null
  [[ ! -e $temporary/office/source/CITYB-CHATGPT-PROPOSAL-PROOF.txt ]] \
    || sc_die 'proposal proof member collides with carried source'
  printf '%s\n' 'complete proposal proof candidate' > "$temporary/office/source/CITYB-CHATGPT-PROPOSAL-PROOF.txt"
  printf '%s\n' 'One added proof member; host tests and adoption remain separate.' > "$temporary/result.txt"
  sc_proposal_close --workspace "$temporary/office" --result "$temporary/result.txt" \
    --disposition recommend --output "$temporary/return.tar.gz" --json > "$temporary/close.json"
  sc_proposal_inspect "$temporary/return.tar.gz" --json > "$temporary/inspect.json"
  grep -F '"current_base_match":true' "$temporary/inspect.json" >/dev/null \
    || sc_die 'proposal proof did not preserve its exact base'
  grep -F '"added":1' "$temporary/inspect.json" >/dev/null \
    || sc_die 'proposal proof change classification differs'
  sc_proposal_materialize "$temporary/return.tar.gz" --out "$temporary/candidate" --json \
    > "$temporary/materialize.json"
  cmp -s "$temporary/office/source/CITYB-CHATGPT-PROPOSAL-PROOF.txt" \
    "$temporary/candidate/CITYB-CHATGPT-PROPOSAL-PROOF.txt" \
    || sc_die 'proposal proof materialized bytes differ'
  ln -s /etc/passwd "$temporary/office/source/PROPOSAL-LINK-ATTACK"
  if "$self" proposal close --workspace "$temporary/office" --result "$temporary/result.txt" \
      --disposition recommend --output "$temporary/unsafe-return.tar.gz" >/dev/null 2>&1; then
    sc_die 'proposal proof admitted a source symlink'
  fi
  if (( json )); then
    printf '{"schema":"cityb.of-chatgpt.proposal-proof.v1","status":"pass","complete_candidate":true,"exact_base":true,"change_classification":true,"materialization":true,"symlink_refusal":true,"network_contacted":false,"host_acceptance":false}\n'
  else
    printf 'CityB-of-ChatGPT proposal proof\nstatus = pass\ncomplete_candidate = pass\nexact_base = pass\nchange_classification = pass\nmaterialization = pass\nsymlink_refusal = pass\nnetwork_contacted = false\nhost_acceptance = false\n'
  fi
  rm -rf -- "$temporary"
  trap - EXIT
}

sc_proposal() {
  local verb=${1:-}
  [[ -n $verb ]] || sc_usage_die 'proposal needs close, inspect, materialize, or proof'
  shift
  case $verb in
    close) sc_proposal_close "$@" ;;
    inspect|verify) sc_proposal_inspect "$@" ;;
    materialize) sc_proposal_materialize "$@" ;;
    proof) sc_proposal_proof "$@" ;;
    *) sc_usage_die 'proposal needs close, inspect, verify, materialize, or proof' ;;
  esac
}

sc_cockpit() {
  local cityb
  cityb=$(sc_binary cityb)
  printf 'CITYB OF CHATGPT\nsource = %s\npayload = %s\nDatacube = rev1227 / %s\n' \
    "$SC_SOURCE_REVISION" "$SC_PAYLOAD_SHA256" "$SC_DATACUBE_KERNEL_SHA256"
  printf 'grantor_authority = explicit\nchatgpt_operator_authority = granted-by-office-policy\n\n'
  "$cityb" next "$@"
}

sc_source() {
  local verb=${1:-} root out='' busybox=''
  [[ -n $verb ]] || sc_usage_die 'source needs list or extract'
  shift
  root=$(sc_payload_root)
  case $verb in
    list)
      (( $# == 0 )) || sc_usage_die 'source list takes no arguments'
      if command -v tar >/dev/null 2>&1 && command -v gzip >/dev/null 2>&1; then
        tar -tzf "$root/source/cityb-source.tar.gz"
      else
        busybox=$(sc_bootstrap_busybox)
        "$busybox" tar -tzf "$root/source/cityb-source.tar.gz"
      fi
      ;;
    extract)
      while (( $# )); do
        case $1 in
          --out) (( $# >= 2 )) || sc_usage_die '--out needs a directory'; out=$2; shift 2 ;;
          *) sc_usage_die "unknown source extract argument: $1" ;;
        esac
      done
      [[ -n $out ]] || sc_usage_die 'source extract requires --out DIR'
      [[ ! -e $out && ! -L $out ]] || sc_die "source output must be absent: $out"
      sc_source_extract_into "$out"
      printf 'source = %s\nrevision = %s\nstatus = verified\n' "$out" "$SC_SOURCE_REVISION"
      ;;
    *) sc_usage_die "unknown source verb: $verb" ;;
  esac
}

sc_manifest() {
  local root
  root=$(sc_payload_root)
  cat "$root/MANIFEST.sha256"
}

sc_install() {
  local bin_dir=${HOME:?HOME is required}/.local/bin destination temporary self
  while (( $# )); do
    case $1 in
      --bin-dir) (( $# >= 2 )) || sc_usage_die '--bin-dir needs a directory'; bin_dir=$2; shift 2 ;;
      *) sc_usage_die "unknown install argument: $1" ;;
    esac
  done
  mkdir -p -- "$bin_dir"
  [[ -d $bin_dir && ! -L $bin_dir ]] || sc_die 'install bin directory is unsafe'
  destination=$bin_dir/CityB-of-ChatGPT.sh
  self=$(sc_self)
  if [[ -e $destination || -L $destination ]]; then
    if [[ -f $destination && ! -L $destination && $(sha256sum "$destination" | awk '{print $1}') == $(sha256sum "$self" | awk '{print $1}') ]]; then
      printf 'install = identical\npath = %s\n' "$destination"
      return 0
    fi
    sc_die "install destination already exists with different bytes: $destination"
  fi
  temporary=$(mktemp "$bin_dir/.CityB-of-ChatGPT.XXXXXXXX")
  trap "rm -f -- $(printf '%q' "$temporary")" EXIT
  install -m 755 -- "$self" "$temporary"
  ln -- "$temporary" "$destination" || sc_die 'could not publish install destination'
  rm -f -- "$temporary"
  trap - EXIT
  printf 'install = complete\npath = %s\nsha256 = %s\n' "$destination" "$(sha256sum "$destination" | awk '{print $1}')"
}

sc_selftest() {
  local temporary root cityb node biggun datacube argon2 encoded expected role
  temporary=$(mktemp -d)
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  CITYB_OF_CHATGPT_HOME=$temporary/cache
  export CITYB_OF_CHATGPT_HOME
  sc_verify_payload 0 >/dev/null
  root=$(sc_payload_root)
  if find "$root/share" -maxdepth 1 -type f \
    | grep -E '(CANONICAL-ANSWERS|VERIFIER|\.answers$)' >/dev/null; then
    sc_die 'payload share exposes constitutional answer material'
  fi
  if command -v tar >/dev/null 2>&1 && command -v gzip >/dev/null 2>&1; then
    tar -tzf "$root/source/cityb-source.tar.gz" > "$temporary/source-members"
  else
    "$(sc_bootstrap_busybox)" tar -tzf "$root/source/cityb-source.tar.gz" > "$temporary/source-members"
  fi
  if grep -E 'fixtures/cityb/chatgpt-.*\.answers$|fixtures/cityb/chatgpt-.*study.*\.json$' \
    "$temporary/source-members" >/dev/null; then
    sc_die 'source archive exposes maintainer-only constitutional fixtures'
  fi
  cityb=$root/bin/$SC_PAYLOAD_ARCH/cityb
  node=$root/bin/$SC_PAYLOAD_ARCH/cityb-node
  biggun=$root/bin/$SC_PAYLOAD_ARCH/cityb-biggun
  datacube=$root/custody/datacube-rev1227/datacube
  argon2=$root/bin/$SC_PAYLOAD_ARCH/argon2
  "$cityb" version --json | grep -q '"binary":"cityb"' || sc_die 'Goldilocks version smoke failed'
  "$node" version --json | grep -q '"binary":"cityb-node"' || sc_die 'Tiny version smoke failed'
  "$biggun" version --json | grep -q '"binary":"cityb-biggun"' || sc_die 'Biggun version smoke failed'
  "$cityb" correspondence help | grep -q 'correspondence remote call' \
    || sc_die 'external operator command surface is absent'
  "$cityb" correspondence help | grep -q 'correspondence office-kit' \
    || sc_die 'public office-kit command surface is absent'
  sc_office_modes | grep -q '^remote ' || sc_die 'operator mode card is incomplete'
  "$datacube" inspect --expect-sha256 "$SC_DATACUBE_KERNEL_SHA256" >/dev/null || sc_die 'Datacube inspection failed'
  awk 'BEGIN { for (i = 0; i < 36; i++) print "AAAA" }' > "$temporary/core-wrong"
  if sc_prompt_verify "$temporary/core-wrong" 0 >/dev/null 2>&1; then
    sc_die 'constitutional verifier accepted a wrong transcript'
  fi
  for role in reading goldilocks tiny biggun; do
    awk 'BEGIN { for (i = 0; i < 44; i++) print "AAAA" }' > "$temporary/$role-role-wrong"
    if sc_role_prompt_verify "$role" "$temporary/$role-role-wrong" 0 >/dev/null 2>&1; then
      sc_die "$role role verifier accepted a wrong transcript"
    fi
  done
  awk 'BEGIN { for (i = 0; i < 55; i++) print "AAAA" }' > "$temporary/choir-wrong"
  if sc_choir_evaluate "$temporary/choir-wrong" 0 1 >/dev/null 2>&1; then
    sc_die 'Choir Gate accepted a wrong transcript'
  fi
  encoded=$(printf 'cityb-selftest' | "$argon2" 'cityb-selftest-v1' -id -v 13 -k 8192 -t 1 -p 1 -l 16 -e)
  # This is an exact encoded known-answer value.
  # shellcheck disable=SC2016
  expected='$argon2id$v=19$m=8192,t=1,p=1$Y2l0eWItc2VsZnRlc3QtdjE$zyvrAVEC9js5yGCrTrTYSQ'
  [[ $encoded == "$expected" ]] || sc_die 'Argon2 known-answer test failed'
  printf 'CityB-of-ChatGPT selftest\nstatus = pass\npayload = %s\nGoldilocks = pass\nTiny = pass\nBiggun = pass\nDatacube = pass\nArgon2id = pass\nconstitutional_refusal = pass\nrole_office_refusal = pass\nchoir_refusal = pass\nanswer_oracle_embedded = false\nexternal_operator_surface = pass\npublic_office_kit_surface = pass\nnetwork_contacted = false\n' "$SC_PAYLOAD_SHA256"
  rm -rf -- "$temporary"
  trap - EXIT
}

sc_assemble() {
  local source_root='' portable_bin_dir='' argon2_bin='' busybox_bin='' datacube_archive='' output=''
  local temporary payload source_list source_manifest source_archive payload_archive
  local payload_sha payload_bytes source_revision source_tree_sha datacube_kernel
  while (( $# )); do
    case $1 in
      --source-root) (( $# >= 2 )) || sc_usage_die '--source-root needs a directory'; source_root=$2; shift 2 ;;
      --portable-bin-dir) (( $# >= 2 )) || sc_usage_die '--portable-bin-dir needs a directory'; portable_bin_dir=$2; shift 2 ;;
      --argon2-bin) (( $# >= 2 )) || sc_usage_die '--argon2-bin needs a file'; argon2_bin=$2; shift 2 ;;
      --busybox-bin) (( $# >= 2 )) || sc_usage_die '--busybox-bin needs a file'; busybox_bin=$2; shift 2 ;;
      --datacube-archive) (( $# >= 2 )) || sc_usage_die '--datacube-archive needs a file'; datacube_archive=$2; shift 2 ;;
      --output) (( $# >= 2 )) || sc_usage_die '--output needs a file'; output=$2; shift 2 ;;
      *) sc_usage_die "unknown assemble argument: $1" ;;
    esac
  done
  [[ -n $source_root && -n $portable_bin_dir && -n $argon2_bin && -n $busybox_bin && -n $datacube_archive && -n $output ]] \
    || sc_usage_die 'assemble requires --source-root, --portable-bin-dir, --argon2-bin, --busybox-bin, --datacube-archive, and --output'
  [[ -d $source_root/.git ]] || sc_die 'source root must be a Git worktree root'
  git -C "$source_root" diff --quiet --ignore-submodules -- \
    || sc_die 'source root has unstaged tracked changes; commit them before sealing'
  git -C "$source_root" diff --cached --quiet --ignore-submodules -- \
    || sc_die 'source root has staged tracked changes; commit them before sealing'
  [[ ! -e $output && ! -L $output ]] || sc_die 'assemble output must be absent'
  for executable in cityb cityb-node cityb-biggun; do
    [[ -x $portable_bin_dir/$executable && ! -L $portable_bin_dir/$executable ]] || sc_die "portable binary is absent: $executable"
    file "$portable_bin_dir/$executable" | grep -Eq 'statically linked|static-pie linked' || sc_die "$executable is not a static Linux executable"
  done
  [[ -x $argon2_bin && ! -L $argon2_bin ]] || sc_die 'Argon2 binary is absent or unsafe'
  file "$argon2_bin" | grep -Eq 'statically linked|static-pie linked' || sc_die 'Argon2 binary is not static'
  [[ -x $busybox_bin && ! -L $busybox_bin ]] || sc_die 'BusyBox bootstrap is absent or unsafe'
  file "$busybox_bin" | grep -Eq 'statically linked|static-pie linked' || sc_die 'BusyBox bootstrap is not static'
  [[ $(sha256sum "$busybox_bin" | awk '{print $1}') == "$SC_BOOTSTRAP_BUSYBOX_SHA256" ]] || sc_die 'BusyBox bootstrap identity differs'
  [[ $(wc -c < "$busybox_bin" | tr -d '[:space:]') == "$SC_BOOTSTRAP_BUSYBOX_BYTES" ]] || sc_die 'BusyBox bootstrap length differs'
  [[ $(sha256sum "$datacube_archive" | awk '{print $1}') == "$SC_DATACUBE_ARCHIVE_SHA256" ]] || sc_die 'Datacube release archive identity differs'
  temporary=$(mktemp -d)
  trap "rm -rf -- $(printf '%q' "$temporary")" EXIT
  payload=$temporary/cityb-of-chatgpt
  mkdir -p "$payload/bin/$SC_PAYLOAD_ARCH" "$payload/custody/datacube-rev1227" "$payload/source" "$payload/share"
  install -m 755 "$portable_bin_dir/cityb" "$payload/bin/$SC_PAYLOAD_ARCH/cityb"
  install -m 755 "$portable_bin_dir/cityb-node" "$payload/bin/$SC_PAYLOAD_ARCH/cityb-node"
  install -m 755 "$portable_bin_dir/cityb-biggun" "$payload/bin/$SC_PAYLOAD_ARCH/cityb-biggun"
  install -m 755 "$argon2_bin" "$payload/bin/$SC_PAYLOAD_ARCH/argon2"
  install -m 600 "$datacube_archive" "$payload/custody/datacube-rev1227/$SC_DATACUBE_RELEASE"
  unzip -q "$datacube_archive" -d "$payload/custody/datacube-rev1227"
  datacube_kernel=$payload/custody/datacube-rev1227/datacube
  [[ $(sha256sum "$datacube_kernel" | awk '{print $1}') == "$SC_DATACUBE_KERNEL_SHA256" ]] || sc_die 'Datacube kernel identity differs'
  chmod 755 "$datacube_kernel"
  chmod 600 "$payload/custody/datacube-rev1227/BOOTSTRAPROSE.md"
  sc_prompt_text > "$payload/share/CHATGPT-CONSTITUTIONAL-QUESTIONNAIRE.txt"
  sc_choir_prompt_text > "$payload/share/CHOIR-CONSTITUTION-v2-QUESTIONNAIRE.txt"
  for role in reading goldilocks tiny biggun; do
    sc_role_prompt_text "$role" > "$payload/share/CHATGPT-${role^^}-OFFICE-QUESTIONNAIRE.txt"
  done
  awk '/^__CITYB_OF_CHATGPT_BOOTSTRAP_BEGIN__$/ { exit } { print }' "$(sc_self)" > "$payload/share/CityB-of-ChatGPT-prefix.sh"
  source_list=$temporary/source-files.txt
  source_manifest=$temporary/SOURCE-MANIFEST.sha256
  # Maintainer-only acceptance transcripts and study outputs exercise the gate
  # during repository checks. They are deliberately absent from the officer
  # artifact, its source archive, its prefix, and every extracted payload member.
  (cd "$source_root" && git ls-files \
    | grep -v '^CityB-of-ChatGPT\.sh$' \
    | grep -Ev '^fixtures/cityb/chatgpt-.*\.answers$' \
    | grep -Ev '^fixtures/cityb/chatgpt-.*study.*\.json$') > "$source_list"
  [[ -s $source_list ]] || sc_die 'tracked source inventory is empty'
  (cd "$source_root" && while IFS= read -r path; do sha256sum "$path"; done < "$source_list") > "$source_manifest"
  source_tree_sha=$(sha256sum "$source_manifest" | awk '{print $1}')
  source_archive=$payload/source/cityb-source.tar.gz
  (
    local staging parent
    staging=$temporary/source-staging
    mkdir "$staging"
    while IFS= read -r path; do
      parent=${path%/*}
      [[ $parent == "$path" ]] && parent=.
      mkdir -p "$staging/$parent"
      cp -p -- "$source_root/$path" "$staging/$path"
    done < "$source_list"
    install -m 600 "$source_manifest" "$staging/SOURCE-MANIFEST.sha256"
    cd "$staging"
    tar --sort=name --mtime='@0' --owner=0 --group=0 --numeric-owner -cf - . | gzip -n > "$source_archive"
  )
  source_revision=$(git -C "$source_root" rev-parse --verify HEAD)
  cat > "$payload/share/BUILD-RECIPE.md" <<'EOF'
# CityB of ChatGPT build receipt

The sealed x86-64 CityB executables were produced from the carried source with
the repository flake's `cityb-portable` musl lane:

    nix build .#cityb-portable

This donor-side command is not a receiving-runtime dependency. A Nix-less
reproduction may install a pinned Rust toolchain plus the x86_64-unknown-linux-
musl target and musl compiler in a disposable Debian/Ubuntu builder, then run:

    cargo build --locked --release --target x86_64-unknown-linux-musl \\
      -p cityb-cli -p cityb-node -p cityb-lab

Compare all output digests with MANIFEST.sha256. The Argon2 CLI is the upstream
libargon2 command compiled statically against musl. The Datacube custody object
is copied from its exact deterministic release ZIP; Datacube's own embedded
source, source-verify, source-materialize, checkpoint, and construction commands
remain its authoritative reproduction surface.

The publication file was then sealed by its own `assemble` command. Build
tools are allowed to use Nix; the resulting receiving product does not.
EOF
  cat > "$payload/share/BUILD-RECEIPT.json" <<EOF
{"schema":"cityb.of-chatgpt.build-receipt.v1","source_revision":"$source_revision","source_manifest_sha256":"$source_tree_sha","payload_arch":"$SC_PAYLOAD_ARCH","cityb_build":"musl-static","bootstrap_busybox_version":"$SC_BOOTSTRAP_BUSYBOX_VERSION","bootstrap_busybox_sha256":"$SC_BOOTSTRAP_BUSYBOX_SHA256","datacube_release":"$SC_DATACUBE_RELEASE","datacube_archive_sha256":"$SC_DATACUBE_ARCHIVE_SHA256","datacube_kernel_sha256":"$SC_DATACUBE_KERNEL_SHA256","nix_receiving_dependency":false}
EOF
  (
    cd "$payload"
    # MANIFEST.sha256 is explicitly excluded from the read side.
    # shellcheck disable=SC2094
    find . -type f ! -name MANIFEST.sha256 -print0 | sort -z | xargs -0 sha256sum > MANIFEST.sha256
  )
  payload_archive=$temporary/payload.tar.gz
  (cd "$temporary" && tar --sort=name --mtime='@0' --owner=0 --group=0 --numeric-owner -cf - cityb-of-chatgpt | gzip -n > "$payload_archive")
  payload_sha=$(sha256sum "$payload_archive" | awk '{print $1}')
  payload_bytes=$(wc -c < "$payload_archive" | tr -d '[:space:]')
  {
    awk -v sha="$payload_sha" -v bytes="$payload_bytes" -v revision="$source_revision" '
      /^SC_PAYLOAD_SHA256=/ { print "SC_PAYLOAD_SHA256=\047" sha "\047"; next }
      /^SC_PAYLOAD_BYTES=/ { print "SC_PAYLOAD_BYTES=\047" bytes "\047"; next }
      /^SC_SOURCE_REVISION=/ { print "SC_SOURCE_REVISION=\047" revision "\047"; next }
      /^__CITYB_OF_CHATGPT_BOOTSTRAP_BEGIN__$/ { print; exit }
      { print }
    ' "$(sc_self)"
    base64 -w 76 "$busybox_bin"
    printf '%s\n' '__CITYB_OF_CHATGPT_BOOTSTRAP_END__'
    printf '%s\n' '__CITYB_OF_CHATGPT_PAYLOAD_BEGIN__'
    base64 -w 76 "$payload_archive"
    printf '%s\n' '__CITYB_OF_CHATGPT_PAYLOAD_END__'
  } > "$output"
  chmod 755 "$output"
  printf 'output = %s\nsource_revision = %s\npayload_sha256 = %s\npayload_bytes = %s\nDatacube_archive_sha256 = %s\n' \
    "$output" "$source_revision" "$payload_sha" "$payload_bytes" "$SC_DATACUBE_ARCHIVE_SHA256"
  rm -rf -- "$temporary"
  trap - EXIT
}

sc_main() {
  local command=${1:-cockpit} json=0 input verb office
  (( $# == 0 )) || shift
  case $command in
    help|-h|--help) (( $# == 0 )) || sc_usage_die 'help takes no arguments'; sc_help ;;
    manual) (( $# == 0 )) || sc_usage_die 'manual takes no arguments'; sc_manual ;;
    version|-V|--version) sc_version "$@" ;;
    doctor) sc_doctor "$@" ;;
    verify)
      [[ ${1:-} == --json ]] && { json=1; shift; }
      (( $# == 0 )) || sc_usage_die 'verify accepts only --json'
      sc_verify_payload "$json"
      ;;
    open) sc_open "$@" ;;
    cockpit) sc_cockpit "$@" ;;
    cityb) sc_dispatch cityb "$@" ;;
    node) sc_dispatch cityb-node "$@" ;;
    biggun) sc_dispatch cityb-biggun "$@" ;;
    datacube) sc_dispatch datacube "$@" ;;
    prompt)
      case ${1:-} in
        print) (( $# == 1 )) || sc_usage_die 'prompt print takes no arguments'; sc_prompt_text ;;
        verify)
          verb=$1
          (( $# >= 2 )) || sc_usage_die "prompt $verb requires an answers file"
          input=$2
          shift 2
          [[ ${1:-} == --json ]] && { json=1; shift; }
          (( $# == 0 )) || sc_usage_die "prompt $verb accepts only ANSWERS [--json]"
          sc_prompt_verify "$input" "$json"
          ;;
        caesar|password)
          verb=$1
          (( $# >= 2 )) || sc_usage_die "prompt $verb requires an answers file"
          input=$2
          office=reading
          shift 2
          while (( $# )); do
            case $1 in
              --office) (( $# >= 2 )) || sc_usage_die '--office needs a value'; office=$2; shift 2 ;;
              --json) json=1; shift ;;
              *) sc_usage_die "unknown prompt $verb argument: $1" ;;
            esac
          done
          sc_office_shift "$office" >/dev/null
          if [[ $verb == caesar ]]; then
            sc_prompt_caesar "$input" "$office" "$json"
          else
            sc_prompt_password "$input" "$office" "$json"
          fi
          ;;
        office)
          (( $# >= 3 )) || sc_usage_die 'prompt office needs print OFFICE or verify|password OFFICE ANSWERS [--json]'
          verb=$2
          office=$3
          sc_office_shift "$office" >/dev/null
          case $verb in
            print)
              (( $# == 3 )) || sc_usage_die 'prompt office print needs exactly OFFICE'
              sc_role_prompt_text "$office"
              ;;
            verify|password)
              (( $# >= 4 )) || sc_usage_die "prompt office $verb needs OFFICE ANSWERS"
              input=$4
              shift 4
              [[ ${1:-} == --json ]] && { json=1; shift; }
              (( $# == 0 )) || sc_usage_die "prompt office $verb accepts only OFFICE ANSWERS [--json]"
              if [[ $verb == verify ]]; then
                sc_role_prompt_verify "$office" "$input" "$json"
              else
                sc_role_prompt_password "$office" "$input" "$json"
              fi
              ;;
            *) sc_usage_die 'prompt office needs print, verify, or password' ;;
          esac
          ;;
        choir)
          (( $# >= 2 )) || sc_usage_die 'prompt choir needs print, score, verify, assist, or password'
          verb=$2
          case $verb in
            print)
              (( $# == 2 )) || sc_usage_die 'prompt choir print takes no arguments'
              sc_choir_prompt_text
              ;;
            score|verify|assist|password)
              (( $# >= 3 )) || sc_usage_die "prompt choir $verb needs an answers file"
              input=$3
              shift 3
              [[ ${1:-} == --json ]] && { json=1; shift; }
              (( $# == 0 )) || sc_usage_die "prompt choir $verb accepts only ANSWERS [--json]"
              case $verb in
                score) sc_choir_evaluate "$input" "$json" 0 ;;
                verify) sc_choir_evaluate "$input" "$json" 1 ;;
                assist) sc_choir_assist "$input" "$json" ;;
                password) sc_choir_password "$input" "$json" ;;
              esac
              ;;
            *) sc_usage_die 'prompt choir needs print, score, verify, assist, or password' ;;
          esac
          ;;
        *) sc_usage_die 'prompt needs print, verify, caesar, password, office, or choir' ;;
      esac
      ;;
    identity)
      verb=${1:-}
      [[ -n $verb ]] || sc_usage_die 'identity needs derive, suite, recover, open, office, or choir'
      shift
      case $verb in
        derive) sc_identity_derive "$@" ;;
        suite) sc_identity_suite "$@" ;;
        recover) sc_identity_recover "$@" ;;
        open) sc_identity_open "$@" ;;
        office)
          verb=${1:-}; [[ -n $verb ]] || sc_usage_die 'identity office needs derive, recover, or open'; shift
          case $verb in
            derive) sc_role_identity_derive "$@" ;;
            recover) sc_role_identity_recover "$@" ;;
            open) sc_role_identity_open "$@" ;;
            *) sc_usage_die 'identity office needs derive, recover, or open' ;;
          esac
          ;;
        choir)
          verb=${1:-}; [[ -n $verb ]] || sc_usage_die 'identity choir needs derive, recover, or open'; shift
          case $verb in
            derive) sc_choir_identity_derive "$@" ;;
            recover) sc_choir_identity_recover "$@" ;;
            open) sc_choir_identity_open "$@" ;;
            *) sc_usage_die 'identity choir needs derive, recover, or open' ;;
          esac
          ;;
        *) sc_usage_die 'identity needs derive, suite, recover, open, office, or choir' ;;
      esac
      ;;
    office) sc_office "$@" ;;
    proposal) sc_proposal "$@" ;;
    source) sc_source "$@" ;;
    manifest) (( $# == 0 )) || sc_usage_die 'manifest takes no arguments'; sc_manifest ;;
    install) sc_install "$@" ;;
    selftest) (( $# == 0 )) || sc_usage_die 'selftest takes no arguments'; sc_selftest ;;
    assemble) sc_assemble "$@" ;;
    *) sc_usage_die "unknown command: $command" ;;
  esac
}

sc_main "$@"
exit $?

